/** 브랜드 캐릭터/IP 자산 목록: /api/ip/library?brandId=. read+synthesize. */
/**
 * 브랜드 id 해석. 대소문자·표기가 조금 달라도 실제 등록된 브랜드를 찾아준다.
 * (브랜드 허브가 저장하는 GCS 경로는 대소문자를 구분해서, "shapes" vs "SHAPES" 가 다른 폴더가 된다.
 *  이 불일치 때문에 "등록된 캐릭터 시트가 없다"는 오답이 나왔다.)
 */
async function resolveBrandId(given: string, ctx: ToolContext): Promise<{ brandId: string; candidates: string[] }> {
  const wanted = String(given || "").trim();
  let ids: string[] = [];
  try {
    const list = await callInternalJson(ctx, "/api/brand/list");
    ids = (Array.isArray(list?.ids) ? list.ids : []).map((v: any) => String(v));
  } catch { /* 목록 조회 실패 시 주어진 값 그대로 사용 */ }
  if (!ids.length) return { brandId: wanted, candidates: [] };
  const exact = ids.find((id) => id === wanted);
  if (exact) return { brandId: exact, candidates: ids };
  const ci = ids.find((id) => id.toLowerCase() === wanted.toLowerCase());
  if (ci) return { brandId: ci, candidates: ids };
  // 이름 일부만 말한 경우(예: "모양새" → shapes)까지는 못 맞추므로, 브랜드가 하나면 그것으로 본다.
  if (!wanted && ids.length === 1) return { brandId: ids[0], candidates: ids };
  if (ids.length === 1) return { brandId: ids[0], candidates: ids };
  return { brandId: wanted, candidates: ids };
}

/**
 * IP(캐릭터 시트) 목록. 두 출처를 합쳐서 본다.
 *  ① 브랜드 정의(reference/data.json)의 characterSheets — 브랜드 허브 'IP 라이브러리' UI 가 쓰는 곳(권위 있는 등록부)
 *  ② GCS brands/<id>/ip/ 파일 목록 — brand_asset 등으로 직접 올라간 파일
 * 예전엔 ②만 봤는데, UI 등록분은 ①에 있어서 "자산이 비어있다"는 오답이 났다.
 * 이미지 바이트(data: URL)는 절대 실어 보내지 않는다 — 대신 ref 키로 나중에 서버가 해석한다.
 */
async function runIpLibraryTool(input: any, ctx: ToolContext): Promise<any> {
  const givenBrand = String(input?.brandId || input?.slug || input?.brand || "").trim();
  const projectId = String(input?.projectId || "").trim();
  if (!givenBrand && !projectId) throw new Error("brandId 또는 projectId 필요");

  let brandId = givenBrand;
  let brandCandidates: string[] = [];
  if (!projectId) {
    const resolved = await resolveBrandId(givenBrand, ctx);
    brandId = resolved.brandId;
    brandCandidates = resolved.candidates;
  }

  // ① 브랜드 정의에 등록된 캐릭터 시트
  const characters: any[] = [];
  let hub: any = null;
  if (brandId) {
    try {
      const got: any = await runBrandGetTool({ brandId }, ctx);
      hub = readBrandHub(got?.brand);
      // 캐릭터별 현재 텍스트 속성(생김새·안 나오게 할 것)을 함께 싣는다.
      // 이게 없으면 에이전트가 "지금 뭐라고 적혀 있는지" 를 모른 채 덮어쓰려 든다.
      const textByToken = new Map<string, { description: string; negativePrompt: string }>();
      const bChars = Array.isArray(got?.brand?.brandCharacters) ? got.brand.brandCharacters : [];
      for (const c of bChars) {
        const t = String(c?.trigger || c?.token || "").trim().toLowerCase();
        if (!t) continue;
        textByToken.set(t, {
          description: String(c?.description || "").trim(),
          negativePrompt: String(c?.negativePrompt || "").trim(),
        });
      }
      const sheets = Array.isArray(got?.brand?.characterSheets) ? got.brand.characterSheets : [];
      for (const entry of sheets) {
        const items = Array.isArray(entry?.items) ? entry.items : [];
        if (!items.length) continue;
        const token = String(entry?.token || "").trim();
        const name = String(entry?.displayName || token.replace(/^@/, "")).trim();
        const text = textByToken.get(token.toLowerCase()) || { description: "", negativePrompt: "" };
        characters.push({
          name,
          token,
          sheetCount: items.length,
          // image 도구의 referenceImages 에 그대로 넣을 수 있는 참조 키(용량 0).
          ref: `ip:${brandId}:${token || name}`,
          description: text.description,
          negativePrompt: text.negativePrompt,
        });
      }
    } catch { /* 브랜드 정의가 없으면 ②만 본다 */ }
  }

  // ② GCS 파일 목록(직접 업로드분)
  let files: any[] = [];
  try {
    const qs = projectId ? `projectId=${encodeURIComponent(projectId)}` : `brandId=${encodeURIComponent(brandId)}`;
    const data = await callInternalJson(ctx, `/api/ip/library?${qs}`);
    files = (Array.isArray(data?.items) ? data.items : [])
      .slice(0, 20)
      .map((it: any) => ({ name: String(it?.name || "").split("/").slice(-2).join("/"), imageUrl: String(it?.signedUrl || "") }));
  } catch { /* 목록 실패는 무시 — ①만으로도 답할 수 있다 */ }

  const count = characters.length || files.length;
  return {
    kind: "ip_library",
    brandId: brandId || undefined,
    projectId: projectId || undefined,
    count,
    // 허브센터 맥락. 이걸 같이 줘야 이 IP 의 세계관·톤·금칙어를 알고 서술할 수 있다.
    hub: hub || undefined,
    characters,
    files,
    brandCandidates: characters.length ? undefined : brandCandidates,
    note: count === 0 && brandCandidates.length
      ? `이 브랜드에는 등록 시트가 없어요. 등록된 브랜드: ${brandCandidates.join(", ")} — 다른 브랜드일 수 있으니 확인해 주세요.`
      : undefined,
  };
}

/**
 * 브랜드 허브센터 맥락.
 *
 * 시트 이미지만 보고 프롬프트를 쓰면 이 IP 가 어떤 세계관인지 모른 채 눈에 보이는
 * 것만 받아적게 된다("빨간 삼각형 캐릭터"). 세계관·톤·규칙·금칙어를 같이 넘겨야
 * 이 IP 의 규격으로 서술된다.
 */
function readBrandHub(brand: any) {
  if (!brand || typeof brand !== "object") return null;
  return {
    brandTitle: String(brand.brandTitle || "").trim(),
    brandStory: String(brand.brandStory || "").trim(),
    worldSetting: String(brand.worldSetting || "").trim(),
    brandVoice: String(brand.brandVoice || "").trim(),
    brandRules: Array.isArray(brand.brandRules) ? brand.brandRules : [],
    bannedExpressions: Array.isArray(brand.bannedExpressions) ? brand.bannedExpressions : [],
  };
}

/** 브랜드 안에서 캐릭터 하나를 찾는다(이름 또는 @토큰, 대소문자 무시). */
function findBrandCharacter(brand: any, wanted: string) {
  const key = String(wanted || "").trim().replace(/^@/, "").toLowerCase();
  if (!key) return null;
  const list = Array.isArray(brand?.brandCharacters) ? brand.brandCharacters : [];
  return list.find((c: any) => {
    const token = String(c?.trigger || c?.token || "").replace(/^@/, "").toLowerCase();
    const name = String(c?.name || "").toLowerCase();
    return token === key || name === key;
  }) || null;
}

/**
 * 등록된 IP 시트를 허브 맥락과 함께 분석해 텍스트 속성 초안을 만든다.
 *
 * 시트는 저장될 때 gs:// 로 올라가므로 서버가 직접 읽는다(채팅 첨부와 달리 실제 주소가 있다).
 * 초안만 돌려주고 저장하지는 않는다 — 저장은 ip_text_save 가 한다.
 */
async function runIpDescribeTool(input: any, ctx: ToolContext): Promise<any> {
  const resolved = await resolveBrandId(String(input?.brandId || input?.brand || input?.slug || ""), ctx);
  const brandId = resolved.brandId;
  if (!brandId) throw new Error("brandId 를 특정하지 못했어요.");
  const wanted = String(input?.character || input?.token || input?.name || "").trim();
  if (!wanted) throw new Error("character(캐릭터 이름 또는 @토큰)가 필요해요.");

  const got: any = await runBrandGetTool({ brandId }, ctx);
  if (!got?.exists) throw new Error("브랜드를 찾지 못했어요.");
  const hub = readBrandHub(got.brand);

  const sheets = Array.isArray(got.brand?.characterSheets) ? got.brand.characterSheets : [];
  const key = wanted.replace(/^@/, "").toLowerCase();
  const entry = sheets.find((e: any) => {
    const token = String(e?.token || "").replace(/^@/, "").toLowerCase();
    const name = String(e?.displayName || "").toLowerCase();
    return token === key || name === key;
  });
  const names = sheets.map((e: any) => String(e?.displayName || e?.token || "")).filter(Boolean).join(", ");
  if (!entry) throw new Error("'" + wanted + "' 시트를 찾지 못했어요. 등록된 캐릭터: " + (names || "없음"));

  const imageUrls = (Array.isArray(entry.items) ? entry.items : [])
    .map((it: any) => String(it?.imageDataUrl || it?.imageUrl || it?.url || "").trim())
    .filter(Boolean)
    .slice(0, 4);
  if (!imageUrls.length) throw new Error("'" + wanted + "' 에 등록된 시트 이미지가 없어요.");

  const displayName = String(entry.displayName || entry.token || wanted).replace(/^@/, "");
  const others = sheets
    .map((e: any) => String(e?.displayName || "").trim())
    .filter((n: string) => n && n.toLowerCase() !== displayName.toLowerCase());

  /*
   * ★회사 지식은 절대 넣지 않는다.
   *
   * IP 라이브러리(허브센터)가 오리지널 저장소이고, 회사 지식은 그것을 근거로 파생된다.
   * 그런데 이 도구는 IP 라이브러리에 쓸 초안을 만든다. 여기서 회사 지식을 읽으면
   * 파생물이 원본으로 되돌아가는 고리가 닫힌다 — 회사 지식에 낀 오류가 원본에 박히고,
   * 거기서 다시 회사 지식이 파생되며 오염이 누적된다.
   *
   * 캐릭터 설계 의도는 허브(brandRules·bannedExpressions)에 적어야 한다. 그쪽은 같은
   * 원본 저장소라 되먹임이 아니다. 아래 brandContext 가 그것만 싣는 이유다.
   */
  const data = await callInternalJson(ctx, "/api/ip/analyze", {
    body: {
      characterName: displayName,
      imageUrls,
      lang: "ko",
      brandContext: {
        brandTitle: hub?.brandTitle,
        brandStory: hub?.brandStory,
        worldSetting: hub?.worldSetting,
        brandRules: hub?.brandRules,
        bannedExpressions: hub?.bannedExpressions,
        otherCharacters: others,
      },
    },
  });

  const cur = findBrandCharacter(got.brand, wanted);
  return {
    kind: "ip_describe",
    brandId,
    character: displayName,
    token: String(entry.token || ""),
    analyzedImages: data?.analyzedImages ?? imageUrls.length,
    description: String(data?.description || "").trim(),
    negativePrompt: String(data?.negativePrompt || "").trim(),
    current: {
      description: String(cur?.description || "").trim(),
      negativePrompt: String(cur?.negativePrompt || "").trim(),
    },
    // 무엇을 근거로 썼는지 남긴다. "어디서 본 거냐" 를 사람이 되물어야 하는 상황을 없앤다.
    usedHub: !!(hub && (hub.worldSetting || hub.brandStory || hub.brandRules.length)),
  };
}

/**
 * IP 텍스트 속성 저장: brandCharacters 의 해당 캐릭터만 갱신한다.
 * 사용자가 손으로 다듬어 둔 값을 덮어쓰므로 쓰기 → 승인 게이트(brand_save 와 같은 취급).
 */
async function runIpTextSaveTool(input: any, ctx: ToolContext): Promise<any> {
  const resolved = await resolveBrandId(String(input?.brandId || input?.brand || input?.slug || ""), ctx);
  const brandId = resolved.brandId;
  if (!brandId) throw new Error("brandId 를 특정하지 못했어요.");
  const wanted = String(input?.character || input?.token || input?.name || "").trim();
  if (!wanted) throw new Error("character(캐릭터 이름 또는 @토큰)가 필요해요.");

  const description = input?.description === undefined ? null : String(input.description || "").trim();
  const negativePrompt = input?.negativePrompt === undefined ? null : String(input.negativePrompt || "").trim();
  if (description === null && negativePrompt === null) {
    throw new Error("description(생김새) 또는 negativePrompt(안 나오게 할 것) 중 하나는 있어야 해요.");
  }

  const got: any = await runBrandGetTool({ brandId }, ctx);
  if (!got?.exists) throw new Error("브랜드를 찾지 못했어요.");
  const list = Array.isArray(got.brand?.brandCharacters) ? got.brand.brandCharacters : [];
  const sheets = Array.isArray(got.brand?.characterSheets) ? got.brand.characterSheets : [];
  const key = wanted.replace(/^@/, "").toLowerCase();

  const applyPatch = (c: any) => {
    const patch: Record<string, any> = { ...c };
    if (description !== null) patch.description = description;
    if (negativePrompt !== null) patch.negativePrompt = negativePrompt;
    // 5칸 → 2칸 통합 이후 옛 칸은 쓰지 않는다(character-traits.js 주석 참조).
    patch.fixedTraits = [];
    patch.bannedTraits = [];
    patch.styleGuide = "";
    patch.updatedAt = new Date().toISOString();
    return patch;
  };

  let hit = false;
  const next = list.map((c: any) => {
    const token = String(c?.trigger || c?.token || "").replace(/^@/, "").toLowerCase();
    const name = String(c?.name || "").toLowerCase();
    if (token !== key && name !== key) return c;
    hit = true;
    return applyPatch(c);
  });

  if (!hit) {
    /*
     * brandCharacters 에 없어도 IP 시트가 등록돼 있으면 실재하는 캐릭터다.
     *
     * 실제로 겪은 일: 세모는 시트가 등록돼 있는데 brandCharacters 에는 뚜뮤·네모만 있어
     * 저장이 "'세모' 캐릭터를 찾지 못했어요" 로 실패했다. 화면(knowledge-hub.js
     * syncBrandCharField)은 이럴 때 항목을 새로 만들어 넣는다 — 도구만 더 엄격할 이유가 없다.
     * 같은 규칙으로 맞춘다.
     */
    const sheet = sheets.find((e: any) => {
      const token = String(e?.token || "").replace(/^@/, "").toLowerCase();
      const name = String(e?.displayName || "").toLowerCase();
      return token === key || name === key;
    });
    if (sheet) {
      const token = String(sheet.token || "").trim() || ("@" + wanted.replace(/^@/, ""));
      const name = String(sheet.displayName || "").trim() || token.replace(/^@/, "");
      next.push(applyPatch({
        id: String(sheet.characterId || "").trim() || ("char_" + Date.now()),
        trigger: token,
        name,
        createdAt: new Date().toISOString(),
      }));
      hit = true;
    }
  }

  if (!hit) {
    // 두 출처를 모두 보여준다. 한쪽만 보여주면 "시트는 보이는데 없다고 한다" 는 혼선이 난다.
    const charNames = list.map((c: any) => String(c?.name || c?.trigger || "")).filter(Boolean);
    const sheetNames = sheets.map((e: any) => String(e?.displayName || e?.token || "")).filter(Boolean);
    throw new Error(
      "'" + wanted + "' 캐릭터를 찾지 못했어요. 캐릭터 자산: " + (charNames.join(", ") || "없음") +
      " / 등록 시트: " + (sheetNames.join(", ") || "없음")
    );
  }

  await runBrandSaveTool({ brandId, brand: { brandCharacters: next }, merge: true }, ctx);
  return {
    kind: "ip_text_save",
    brandId,
    character: wanted,
    saved: true,
    description: description === null ? undefined : description,
    negativePrompt: negativePrompt === null ? undefined : negativePrompt,
  };
}

/** 나레이션/음성 생성: /api/tts (Google TTS). external(즉시 실행·검수 패널). */
async function runNarrationTool(input: any, ctx: ToolContext): Promise<any> {
  const script = String(input?.script || input?.text || input?.prompt || "").trim();
  if (!script) throw new Error("script is required (읽을 대본)");
  const data = await callInternalJson(ctx, "/api/tts", {
    body: {
      projectId: String(input?.projectId || "ai-company").trim() || "ai-company",
      sceneId: String(input?.sceneId || `narration_${Date.now()}`).trim(),
      script,
      voiceId: String(input?.voiceId || "kr_female_narration").trim(),
      speakingRate: Number(input?.speakingRate || 1.05),
      pitch: Number(input?.pitch ?? 2),
      voiceName: String(input?.voiceName || "").trim() || undefined,
    },
  });
  return { audioUrl: data.voiceUrl || "", objectName: data.objectName || "", format: data.format || "", kind: "audio", model: "google-tts", promptEcho: script.slice(0, 80) };
}

/** 해시태그 생성: /api/hashtags. 브랜드 정보 기반 SNS 해시태그. read+synthesize. */
async function runHashtagsTool(input: any, ctx: ToolContext): Promise<any> {
  const knowledgeHub: Record<string, any> = {
    brandVoice: input?.brandVoice, brandStory: input?.brandStory,
    brandCharacter: input?.brandCharacter, worldSetting: input?.worldSetting,
    brandRules: input?.brandRules, bannedExpressions: input?.bannedExpressions,
  };
  const data = await callInternalJson(ctx, "/api/hashtags", {
    body: {
      language: input?.language === "en" ? "en" : "ko",
      brandTitle: String(input?.brandTitle || "").trim(),
      brandSummary: String(input?.brandSummary || "").trim(),
      coreMessage: String(input?.coreMessage || "").trim(),
      targetAudience: String(input?.targetAudience || "").trim(),
      contentType: String(input?.contentType || "").trim(),
      brandKeywords: Array.isArray(input?.brandKeywords) ? input.brandKeywords : [],
      sourceTexts: Array.isArray(input?.sourceTexts) ? input.sourceTexts : (input?.caption ? [String(input.caption)] : []),
      knowledgeHub,
    },
  });
  return { kind: "hashtags", hashtags: data.hashtags || [], text: data.text || "" };
}

// ────────────────────────────────────────────────────────────────────────────
// STEP 1 (P0) — 프로덕션 엔드투엔드 뼈대: 프로젝트/에피소드 + 시나리오→씬 + 씬 자산 부착.
// "에피소드 = 별도 projectId"(예: series-ep1). 기존 GCS 데이터 모델(project/get·save의
// {payload, scenes[]}) 그대로 사용. 소유 데이터 쓰기는 전부 gate:true(승인 후 review.ts가 실행).
// ────────────────────────────────────────────────────────────────────────────

/** 프로젝트(에피소드) 생성: /api/project/init. GCS 폴더·빈 data.json 초기화. 쓰기 → 승인 게이트. */
async function runProjectCreateTool(input: any, ctx: ToolContext): Promise<any> {
  // '프로젝트 생성' 폼 필드: 프로젝트 이름(seriesTitle)·에피소드 이름(episodeTitle)·
  // 프로젝트 유형(projectType)·브랜드 요약(brandSummary)·핵심 메시지(coreMessage).
  const seriesTitle = String(input?.seriesTitle || input?.projectName || "").trim();
  const episodeTitle = String(input?.episodeTitle || "").trim();
  const projectType = String(input?.projectType || input?.type || "").trim();
  const brandSummary = String(input?.brandSummary || input?.summary || "").trim();
  const coreMessage = String(input?.coreMessage || input?.message || "").trim();
  // 시리즈 폴더도 이름에서 만든다(한글은 로마자로). 예전엔 projects+타임스탬프였다.
  const seriesId = String(input?.seriesId || "").trim() || toSlug(seriesTitle, 40);
  // ★폴더 이름(projectId)은 항상 사람이 읽는 슬러그다. 모델이 안 주거나, 일련번호(숫자·projects123)를 주거나,
  //   한글처럼 경로에 못 쓰는 글자를 주면 "<시리즈>-<에피소드>" 를 로마자로 만들어 쓴다(같은 이름이 있으면 -2, -3).
  let projectId = String(input?.projectId || input?.id || "").trim();
  let autoNamed = false;
  const readable = !!projectId && /^[a-zA-Z0-9._-]+$/.test(projectId) && !isAutoGeneratedProjectId(projectId);
  if (!readable) {
    const base = [toSlug(seriesId || seriesTitle, 24), toSlug(episodeTitle || input?.title || input?.name, 24)].filter(Boolean).join("-")
      || toSlug(projectId, 40);
    if (!base) throw new Error("프로젝트 이름(seriesTitle)이나 에피소드 이름(episodeTitle)이 필요해요 — 폴더 이름을 그 이름에서 만들어요(숫자 일련번호는 쓰지 않아요).");
    const existing = await callInternalJson(ctx, "/api/project/list").catch(() => null);
    const takenIds: string[] = Array.isArray(existing?.ids) ? existing.ids.map((v: any) => String(v || "")) : [];
    projectId = uniqueSlug(base, takenIds);
    autoNamed = true;
  }
  const data = await callInternalJson(ctx, "/api/project/init", { body: { projectId } });
  // 카드 표시 이름(title): 에피소드 이름 > 일반 title/name > 프로젝트 이름.
  const displayTitle = episodeTitle || String(input?.title || input?.name || "").trim() || seriesTitle;

  const payload: any = {};
  if (seriesTitle) { payload.seriesTitle = seriesTitle; payload.brandTitle = seriesTitle; }
  if (episodeTitle) payload.episodeTitle = episodeTitle;
  if (projectType) payload.projectType = projectType;
  if (brandSummary) payload.brandSummary = brandSummary;
  if (coreMessage) payload.coreMessage = coreMessage;
  if (seriesId) { payload.seriesId = seriesId; payload.brandId = seriesId; }

  if (displayTitle || Object.keys(payload).length) {
    try {
      const saveBody: any = { projectId };
      if (displayTitle) saveBody.title = displayTitle;
      if (Object.keys(payload).length) saveBody.payload = payload;
      await callInternalJson(ctx, "/api/project/save", { body: saveBody });
    } catch (_) {}
  }
  return {
    kind: "project_create", projectId, title: displayTitle,
    seriesTitle, episodeTitle, projectType, brandSummary, coreMessage,
    initialized: Number(data?.initialized ?? 0),
    autoNamed,
    ...(autoNamed ? { notice: `폴더 이름을 '${projectId}' 로 만들었어요(이름에서 만든 슬러그 · 일련번호 아님).` } : {})
  };
}

// 새 에피소드가 부모(시리즈)에서 상속하는 브랜드/시리즈 컨텍스트 필드.
// (에피소드별 콘텐츠 topic/story/purposeCategory/tones/... 는 상속하지 않아 빈 개요로 시작)
const EPISODE_INHERIT_FIELDS = [
  "target", "targetAudience", "aspectRatio", "projectType", "brandSummary", "coreMessage",
  "brandKeywords", "connectedChannels", "brandVoice", "brandTone", "brandStory", "brandCharacter",
  "brandRules", "bannedExpressions", "referenceContents", "successCases", "worldSetting",
  "knowledgeWorld", "knowledgeCharacters", "environmentAssets", "knowledgeHub",
];

/**
 * 기존 프로젝트(시리즈)에 새 에피소드 추가: 부모의 시리즈·브랜드 컨텍스트를 상속해
 * 새 projectId 로 생성. '프로젝트 생성' 폼의 '에피소드' 탭에 대응. 쓰기 → 승인 게이트.
 */
async function runProjectAddEpisodeTool(input: any, ctx: ToolContext): Promise<any> {
  const parentProjectId = String(input?.parentProjectId || input?.sourceProjectId || input?.fromProjectId || "").trim();
  if (!parentProjectId) throw new Error("기준이 될 기존 프로젝트(parentProjectId)가 필요해요. project_list로 확인하세요.");
  const episodeTitle = String(input?.episodeTitle || input?.title || "").trim();

  // 부모 프로젝트 페이로드에서 시리즈·브랜드 컨텍스트 상속.
  const parent = await runProjectGetTool({ projectId: parentProjectId }, ctx);
  const pp: any = (parent && parent.payload && typeof parent.payload === "object") ? parent.payload : {};
  const seriesId = String(input?.seriesId || pp.seriesId || parentProjectId).trim();
  const seriesTitle = String(input?.seriesTitle || pp.seriesTitle || pp.brandTitle || parent.title || "").trim();

  // 새 에피소드 projectId: 사람이 읽는 슬러그 "<시리즈>-<에피소드>"(한글은 로마자). 모델이 준 id 가 일련번호·한글이거나,
  // 부모가 일련번호(1771052245118)라 "-ep2" 를 붙여도 못 읽는 경우엔 이름에서 만든다. 같은 이름이 있으면 -2, -3.
  let projectId = String(input?.projectId || input?.id || "").trim();
  let autoNamed = false;
  const readable = !!projectId && /^[a-zA-Z0-9._-]+$/.test(projectId) && !isAutoGeneratedProjectId(projectId);
  if (!readable) {
    const seriesSlug = toSlug(isAutoGeneratedProjectId(seriesId) ? seriesTitle : (seriesId || seriesTitle), 24);
    const episodeSlug = toSlug(episodeTitle, 24);
    let base = [seriesSlug, episodeSlug].filter(Boolean).join("-");
    if (!base) {
      const m = parentProjectId.match(/^(.*?)-ep(\d+)$/i);
      const stem = m ? m[1] : parentProjectId;
      base = isAutoGeneratedProjectId(stem) ? "" : `${stem}-ep${m ? Number(m[2]) + 1 : 2}`;
    }
    if (!base) throw new Error("에피소드 이름(episodeTitle)이 필요해요 — 폴더 이름을 그 이름에서 만들어요(숫자 일련번호는 쓰지 않아요).");
    const existing = await callInternalJson(ctx, "/api/project/list").catch(() => null);
    const takenIds: string[] = Array.isArray(existing?.ids) ? existing.ids.map((v: any) => String(v || "")) : [];
    projectId = uniqueSlug(base, takenIds);
    autoNamed = true;
  }

  await callInternalJson(ctx, "/api/project/init", { body: { projectId } });

  const displayTitle = episodeTitle || `${seriesTitle || "새"} 새 에피소드`;
  const payload: any = {
    seriesId, seriesTitle,
    brandId: pp.brandId || seriesId,
    brandTitle: pp.brandTitle || seriesTitle,
    episodeTitle: displayTitle,
    parentProjectId, parentProjectTitle: String(parent.title || seriesTitle || ""),
    sourceProjectId: parentProjectId, sourceProjectTitle: String(parent.title || seriesTitle || ""),
  };
  for (const f of EPISODE_INHERIT_FIELDS) { if (pp[f] !== undefined) payload[f] = pp[f]; }
  // 사용자가 명시한 값은 상속을 덮어씀.
  if (input?.projectType != null) payload.projectType = String(input.projectType);
  if (input?.brandSummary != null) payload.brandSummary = String(input.brandSummary);
  if (input?.coreMessage != null) payload.coreMessage = String(input.coreMessage);

  const saveBody: any = { projectId, title: displayTitle, payload };
  if (pp.aspectRatio) saveBody.aspectRatio = pp.aspectRatio;
  await callInternalJson(ctx, "/api/project/save", { body: saveBody });

  return {
    kind: "project_add_episode", projectId, parentProjectId, seriesId, seriesTitle,
    episodeTitle: displayTitle, title: displayTitle,
    autoNamed,
    ...(autoNamed ? { notice: `폴더 이름을 '${projectId}' 로 만들었어요(이름에서 만든 슬러그 · 일련번호 아님).` } : {})
  };
}

/** 프로젝트 표시 이름(title) 변경: /api/project/save 에 title만 저장(payload·scenes 보존). 쓰기 → 승인 게이트. */
async function runProjectRenameTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!projectId) throw new Error("projectId is required");
  const title = String(input?.title || input?.name || input?.newName || "").trim();
  if (!title) throw new Error("새 이름(title)이 필요해요.");
  await callInternalJson(ctx, "/api/project/save", { body: { projectId, title } });
  return { kind: "project_rename", projectId, title, renamed: true };
}

/** 프로젝트 목록: /api/project/list. 내 프로젝트 id + 공유받은 프로젝트. read. */
/** 기한 안에 안 끝나면 fallback. 조회 도구는 30초 예산이라, 무거운 보조 조회(프로젝트 요약)는 15초까지만 기다린다. */
function withDeadline<T>(p: Promise<T>, ms: number, fallback: T): Promise<T> {
  return new Promise<T>((resolve) => {
    const timer = setTimeout(() => resolve(fallback), ms);
    p.then((v) => { clearTimeout(timer); resolve(v); }, () => { clearTimeout(timer); resolve(fallback); });
  });
}
const SUMMARY_DEADLINE_MS = 15000;

async function runProjectListTool(_input: any, ctx: ToolContext): Promise<any> {
  const data = await callInternalJson(ctx, "/api/project/list");
  const ids = Array.isArray(data?.ids) ? data.ids : [];
  const shared = Array.isArray(data?.shared) ? data.shared : [];
  // id 만 주면 모델이 "SHAPES 시리즈" 를 못 찾는다(2026-09-24: 숫자 id 13개만 보고 흐름이 멈춤).
  // 제작 캔버스 선택기와 같은 요약(시리즈·에피소드 제목·컷 수)을 붙인다.
  const summary = await withDeadline(callInternalJson(ctx, "/api/agent/production-projects"), SUMMARY_DEADLINE_MS, null as any);
  const projects = (Array.isArray(summary?.projects) ? summary.projects : []).map((p: any) => ({
    id: String(p?.id || ""), seriesId: String(p?.seriesId || ""), seriesTitle: String(p?.seriesTitle || ""),
    episodeTitle: String(p?.episodeTitle || ""), title: String(p?.title || ""), projectType: String(p?.projectType || ""),
    sceneCount: Number(p?.sceneCount) || 0, stills: Number(p?.stills) || 0, clips: Number(p?.clips) || 0, shared: !!p?.shared,
  })).filter((p: any) => p.id);
  return { kind: "project_list", count: ids.length, ids, shared, projects };
}

/** 프로젝트 상태 조회: /api/project/get?projectId=. {payload, scenes[]} 반환. read+synthesize. */
async function runProjectGetTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!projectId) throw new Error("projectId is required");
  // 공유받은 프로젝트는 소유자 폴더에 있다 — ownerId 를 주면 get 이 권한을 확인하고 그쪽을 읽는다.
  const ownerId = String(input?.ownerId || "").trim();
  const data = await callInternalJson(ctx, `/api/project/get?projectId=${encodeURIComponent(projectId)}${ownerId ? `&ownerId=${encodeURIComponent(ownerId)}` : ""}`);
  // get은 정상이면 {ok, data:{payload, scenes, title...}}, 최초(빈)면 {payload:null, scenes:[], source:"empty"}.
  const d = (data && typeof data.data === "object" && data.data) ? data.data : data;
  const scenes = Array.isArray(d?.scenes) ? d.scenes : [];
  return {
    kind: "project_get", projectId,
    title: d?.title || "", payload: d?.payload ?? null,
    // 프로젝트 공통 헤더(save 가 최상위 header 로 영속). 씬 프롬프트의 COMMON 폴백 원천.
    header: typeof d?.header === "string" ? d.header : "",
    scenes, sceneCount: scenes.length,
  };
}

/** 프로젝트 저장: /api/project/save. payload는 병합, scenes[]는 통째 대체. 쓰기 → 승인 게이트. */
async function runProjectSaveTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!projectId) throw new Error("projectId is required");
  const body: any = { projectId };
  if (input?.payload && typeof input.payload === "object") body.payload = input.payload;
  if (Array.isArray(input?.scenes)) body.scenes = input.scenes;
  if (input?.title) body.title = String(input.title);
  if (input?.aspectRatio) body.aspectRatio = String(input.aspectRatio);
  if (body.payload === undefined && body.scenes === undefined && body.title === undefined) {
    throw new Error("저장할 payload 또는 scenes가 필요해요.");
  }
  const data = await callInternalJson(ctx, "/api/project/save", { body });
  return { kind: "project_save", projectId, saved: true, objectName: data?.objectName || "", merged: !!data?.merged };
}

/** 시나리오 생성 → 그 씬들을 프로젝트에 저장(합성). 엔드투엔드 연결 고리. 쓰기 → 승인 게이트. */
async function runScenarioToProjectTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!projectId) throw new Error("projectId is required (예: series-ep1)");
  const scenario = await runScenarioTool(input, ctx);
  const scenes = Array.isArray(scenario?.scenes) ? scenario.scenes : [];
  if (!scenes.length) throw new Error("시나리오에서 씬이 생성되지 않았어요.");
  const saveBody: any = { projectId, scenes };
  const title = String(input?.title || scenario.topic || "").trim();
  if (title) saveBody.title = title;
  // 프리프로덕션 설정(장르·세부장르·타겟·목적·톤·스타일·길이·음성모드)을 payload 로 저장 →
  // 사이드바/대시보드 카드 메타(장르·타겟·길이)와 음성모드가 폼과 동일하게 반영된다.
  const s = scenario.settings || {};
  saveBody.payload = {
    story: s.story || "",
    purposeCategory: s.purposeCategory || "",
    purposeTags: s.purposeTags || [],
    target: s.target || "",
    needs: s.needs || [],
    tones: s.tones || [],
    styles: s.styles || [],
    duration: s.duration || "",
    aspectRatio: s.aspectRatio || "",
    narrationEnabled: !!s.narrationEnabled,
    dubbingEnabled: !!s.dubbingEnabled,
  };
  if (s.aspectRatio) saveBody.aspectRatio = s.aspectRatio;
  const saved = await callInternalJson(ctx, "/api/project/save", { body: saveBody });
  return {
    kind: "scenario_to_project", projectId,
    sceneCount: scenes.length, topic: scenario.topic, summary: scenario.summary,
    saved: true, objectName: saved?.objectName || "",
  };
}

/** scenes[] 에서 대상 씬 인덱스 찾기 — scene.id 일치 → 숫자 id 일치 → 1-based 순번. 미지정이면 첫 씬. */
function findSceneIndex(scenes: any[], ref: any): number {
  if (ref === undefined || ref === null || String(ref).trim() === "") return scenes.length ? 0 : -1;
  const s = String(ref).trim();
  let idx = scenes.findIndex((sc) => String(sc?.id) === s);
  if (idx >= 0) return idx;
  const num = Number(s.replace(/[^0-9]/g, ""));
  if (Number.isFinite(num) && num > 0) {
    idx = scenes.findIndex((sc) => Number(sc?.id) === num);
    if (idx >= 0) return idx;
    if (num <= scenes.length) return num - 1; // 1-based 순번 폴백
  }
  return -1;
}

/** 씬 스틸컷: image 생성 → 해당 scene.imageDataUrl 에 부착 후 project_save. 쓰기 → 승인 게이트.
 *  이미지는 gs:// 영속 경로로 부착(save가 data: URL은 버리고 gs/https만 보존). */
/** 컷의 @캐릭터 → 브랜드 등록 시트(최대 2장, 대표 먼저) + 등록 설명(인상착의·크기). 스틸(scene_still)·영상(scene_video)이 같은 묶음을 쓴다.
 *  시트가 없는 캐릭터는 note 에 "시트 없음"으로 남기고 프롬프트에 설명만 넘긴다(조용히 빠지면 왜 안 나왔는지 알 수 없다). */
async function collectCharacterRefs(scene: any, payload0: any, ctx: ToolContext): Promise<{ refs: any[]; block: string; note: string; tokens: string[]; names: string[]; missing: string[] }> {
  const refs: any[] = [];
  const brandId = String(payload0.brandId || payload0.brandRef?.id || "").trim();
  const tokenText = String(scene?.composition || scene?.shot || scene?.visual || "");
  // 화면에 나오는 @캐릭터 전원(상한 6). 예전 2명 제한이 세 번째 캐릭터의 시트를 통째로 빼먹었다.
  const tokens = Array.from(new Set((tokenText.match(/@[0-9A-Za-z가-힣_]{1,24}/g) || []).map((t: string) => t.trim()))).slice(0, 6);
  // 등록 설명(인상착의·크기)을 참조 라벨과 프롬프트에 함께 싣는다 — 시트 이미지만으로는 "25cm" 같은 크기를 모델이 알 수 없다.
  const charLines: string[] = [];
  const charNames: string[] = [];
  const charMissing: string[] = [];
  let note = "";
  if (brandId && tokens.length) {
    let brand: any = null;
    try { brand = (await runBrandGetTool({ brandId }, ctx))?.brand || null; } catch { brand = null; }
    for (const tk of tokens) {
      const bc = brand ? findBrandCharacter(brand, tk) : null;
      const name = String(bc?.name || tk.replace(/^@+/, "")).trim();
      const desc = String(bc?.description || "").replace(/\s+/g, " ").trim().slice(0, 240);
      // 등록 시트(이미지)가 있는지 여기서 확인 — 없으면 runImagenTool 이 조용히 빼 버려 "왜 이 캐릭터가 안 나왔나"를 알 수 없었다.
      const norm = (v: any) => String(v || "").replace(/^@+/, "").trim().toLowerCase();
      const sheetEntry = (Array.isArray(brand?.characterSheets) ? brand.characterSheets : []).find((e: any) => norm(e?.token) === norm(tk) || norm(e?.displayName) === norm(tk) || norm(e?.displayName) === norm(name));
      const hasSheet = !!(Array.isArray(sheetEntry?.items) && sheetEntry.items.some((it: any) => String(it?.imageDataUrl || "").trim()));
      if (hasSheet) {
        // 시트를 최대 2장(대표 먼저) 직접 첨부한다 — 한 장(ip: 키)만 붙이면 세 캐릭터 중 하나가 시트와 다르게 나오는 일이 있었다.
        const items: any[] = sheetEntry.items.filter((it: any) => String(it?.imageDataUrl || "").trim());
        const picked = [...items.filter((it: any) => it?.isPrimary), ...items.filter((it: any) => !it?.isPrimary)].slice(0, 2);
        picked.forEach((it: any, k: number) => refs.push({ role: "character", imageUrl: String(it.imageDataUrl).trim(), subjectDescription: `${desc ? `${name} — ${desc}` : name}${picked.length > 1 ? ` (reference sheet ${k + 1} of ${picked.length})` : ""}`, referenceKind: "character" }));
        charNames.push(`${name}×${picked.length}`);
      } else {
        charMissing.push(name);
      }
      charLines.push(`${tk} (${name})${desc ? `: ${desc}` : ""}${hasSheet ? "" : " — NO reference sheet registered; draw from this description"}`);
    }
    note = `캐릭터 ${charNames.length}${charNames.length ? ` (${charNames.join("·")})` : ""}${charMissing.length ? ` · 시트 없음: ${charMissing.join("·")}` : ""}`;
  } else if (tokens.length) {
    note = "캐릭터 0 (브랜드 미연결)";
  }
  const block = charLines.length
    ? [`Exactly ${charLines.length} character${charLines.length > 1 ? "s" : ""} appear in this shot: ${tokens.join(", ")}. ALL of them must be clearly visible in the frame — never omit or merge any of them.`,
       "Registered characters in this shot (match the reference sheets exactly):", ...charLines.map((l) => `- ${l}`),
       "Keep each character's physical size exactly as stated in its description, relative to the furniture and props of the set plate. Do NOT enlarge characters to fill the frame — choose the camera distance instead."].join("\n")
    : "";
  return { refs, block, note, tokens, names: charNames, missing: charMissing };
}

/** 세트 플레이트 게이트: 세트가 등록돼 있는데 부감 마스터도 정면 플레이트도 없으면 컷을 만들지 않는다(힉스필드의 "자산 잠금" 게이트와 같은 뜻).
 *  플레이트 없이 만든 컷은 컷마다 다른 방을 상상하므로 일관성 검증 자체가 무의미하다. input.force === true 면 통과. */
function assertSetPlateReady(loc: any, input: any): void {
  if (!loc || input?.force === true) return;
  if (masterOf(loc) || String(loc.refObjectName || "").trim()) return;
  throw new Error(`세트 "${String(loc.name || "")}"에 배경 플레이트가 없어요. 배경 바의 별 버튼으로 부감 마스터를 먼저 만드세요.`);
}

/** 최신 유효 스토리보드에서 이 컷의 승인된 콘티 패널을 찾는다. 씬 경계/순서가 바뀐 시트는 참조하지 않는다. */
function approvedContiPanel(payload: any, scenes: any[], sceneId: unknown): { sheetId: string; panelIndex: number; objectName: string } | null {
  const sheets: any[] = Array.isArray(payload?.storyboardSheets) ? payload.storyboardSheets.slice() : [];
  sheets.sort((a, b) => String(b?.createdAt || "").localeCompare(String(a?.createdAt || "")));
  for (const sheet of sheets) {
    if (!sheet || sheet.kind !== "board" || isSheetStale(sheet, scenes)) continue;
    const panel = (Array.isArray(sheet.panels) ? sheet.panels : []).find((p: any) =>
      p?.role === "cut" && p?.status === "approved" && String(p?.ref) === String(sceneId) && String(p?.objectName || "").trim());
    if (panel) return { sheetId: String(sheet.id || ""), panelIndex: Number(panel.index) || 0, objectName: String(panel.objectName) };
  }
  return null;
}

async function runSceneStillTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!projectId) throw new Error("projectId is required");
  const cur = await runProjectGetTool({ projectId }, ctx);
  const scenes: any[] = Array.isArray(cur.scenes) ? cur.scenes : [];
  if (!scenes.length) throw new Error("프로젝트에 컷이 없어요. scenario_to_project 로 시나리오를 저장하거나, scene_upsert 로 컷을 하나 만들고 다시 부르세요(사용자에게는 캔버스 '컷 추가' 버튼도 있어요).");
  const idx = findSceneIndex(scenes, input?.sceneId ?? input?.scene ?? input?.sceneIndex);
  if (idx < 0) throw new Error(`씬을 찾지 못했어요(sceneId=${input?.sceneId ?? input?.scene ?? "?"}).`);
  const scene = scenes[idx];
  // 프롬프트는 브라우저 buildImagePrompt 와 같은 조립기로 만든다(명시 prompt 가 오면 그것이 우선).
  const header = String(cur.payload?.header || cur.header || "");
  const prompt = String(input?.prompt || "").trim() || buildSceneImagePrompt(scene, header, {});
  if (!prompt) throw new Error("이미지 프롬프트가 없어요(prompt 또는 씬 화면/비주얼 필요).");
  const bucket = studioBucket(ctx);
  // ★표준 일관성 참조 묶음: 승인 콘티 → 캐릭터 시트 → 부감 마스터.
  // 승인 콘티가 이미 실제 컷의 카메라·배경을 고정하므로 별도 방위 플레이트를 만들지 않는다.
  // 콘티 없이 직접 스틸을 만드는 옛 경로만 방위×높이 플레이트 캐시를 하위 호환으로 사용한다.
  const payload0: any = (cur.payload && typeof cur.payload === "object") ? cur.payload : {};
  const gsOf = (obj: any) => `gs://${bucket}/${String(obj || "").replace(/^gs:\/\/[^/]+\//, "")}`;
  const refs: any[] = [];
  const refNotes: string[] = [];
  let plateVariant = "";
  const conti = approvedContiPanel(payload0, scenes, scene?.id ?? idx + 1);
  if (input?.requireStoryboard === true && !conti) {
    throw new Error(`컷 ${String(scene?.id ?? idx + 1)}에 승인된 스토리보드 콘티가 없어요. 스토리보드를 생성·검토하고 이 컷을 승인한 뒤 스틸컷을 만드세요.`);
  }
  if (conti && bucket) {
    refs.push({ role: "storyboard", imageUrl: gsOf(conti.objectName), referenceId: 1, referenceKind: "conti-panel",
      subjectDescription: `APPROVED STORYBOARD PANEL for cut ${String(scene?.id ?? idx + 1)} — composition, camera, staging and character placement must match exactly` });
    refNotes.push(`승인 콘티 ${conti.sheetId}#${conti.panelIndex}`);
  }
  const chars = await collectCharacterRefs(scene, payload0, ctx);
  for (const r of chars.refs) refs.push({ ...r, referenceId: refs.length + 1 });
  if (chars.note) refNotes.push(chars.note);
  const charBlock = chars.block;
  const contiBlock = conti
    ? "The first reference is the approved storyboard panel. Reproduce its composition, camera angle, framing and staging exactly as a finished frame. Do not reframe it."
    : "";
  const promptSent = [prompt, contiBlock, charBlock].filter(Boolean).join("\n");
  const direction = normalizeCameraDirection(scene?.cameraDirection) || "front";
  const elevation = normalizeCameraElevation(scene?.cameraElevation) || "eye";
  const locations: any[] = Array.isArray(payload0.episodeLocations) ? payload0.episodeLocations : [];
  const locName = String(scene?.sceneLocation || scene?.location || "").trim() || (locations.length === 1 ? String(locations[0]?.name || "") : "");
  let loc: any = locName ? (locations.find((l: any) => normLocationKey(l?.name) === normLocationKey(locName) || normLocationKey(l?.id) === normLocationKey(locName)) || null) : null;
  assertSetPlateReady(loc, input);
  if (loc && bucket) {
    const lockedMaster = masterOf(loc);
    let plate = conti && lockedMaster
      ? { objectName: lockedMaster, variantId: MASTER_VARIANT_ID, exact: false, source: "master" as const }
      : findPlate(loc, direction, elevation);
    const wantId = plateVariantId(direction, elevation);
    if (!conti && (!plate || !plate.exact) && lockedMaster && input?.autoDerivePlate !== false && wantId !== MASTER_VARIANT_ID) {
      try {
        await runSetAngleTool({ projectId, locationName: String(loc.name || locName), direction, elevation, ...(input?.provider ? { provider: String(input.provider) } : {}) }, ctx);
        const again = await runProjectGetTool({ projectId }, ctx);
        const locs2: any[] = Array.isArray(again?.payload?.episodeLocations) ? again.payload.episodeLocations : [];
        loc = locs2.find((l: any) => normLocationKey(l?.name) === normLocationKey(String(loc.name || locName))) || loc;
        plate = findPlate(loc, direction, elevation);
        if (plate && plate.exact) refNotes.push(`플레이트 ${plateLabel(direction, elevation, "ko")}(새로 파생)`);
      } catch (e) {
        if ((e as any)?.subscriptionImage) throw e;
        refNotes.push(`플레이트 파생 실패: ${String((e as Error)?.message || e).slice(0, 80)}`);
      }
    } else if (plate && plate.exact) {
      refNotes.push(`플레이트 ${plateLabel(direction, elevation, "ko")}(${plate.source === "front-legacy" ? "기존 정면" : "캐시 재사용"})`);
    }
    if (plate) {
      plateVariant = plate.variantId;
      const setName = String(loc.name || locName);
      refs.push({ role: "plate", imageUrl: gsOf(plate.objectName), referenceId: refs.length + 1, referenceKind: "environment",
        subjectDescription: plate.exact
          ? `SET PLATE of ${setName} for THIS camera (${plateLabel(direction, elevation, "en")}) — this is the background of the shot; keep walls, windows, furniture and props exactly where they are`
          : plate.source === "master"
            ? `TOP-DOWN MASTER PLATE of ${setName} — layout truth; keep every object on the same wall and position while the camera is ${plateLabel(direction, elevation, "en")}`
            : `FRONT PLATE of ${setName} — this shot faces ${plateLabel(direction, elevation, "en")}; keep the architectural style, palette and lighting, reconstruct the ${direction} side consistently` });
      if (!plate.exact) refNotes.push(plate.source === "master" ? "부감 마스터만(플레이트 없음)" : "정면 플레이트 폴백");
      const master = masterOf(loc);
      if (!conti && plate.exact && master && plate.objectName !== master && refs.length < 12) {
        refs.push({ role: "master", imageUrl: gsOf(master), referenceId: refs.length + 1, referenceKind: "environment", subjectDescription: `TOP-DOWN MASTER PLATE of ${setName} — layout truth (where each piece of furniture stands); do not copy its top-down camera` });
        refNotes.push("부감 마스터");
      }
    }
  } else if (locName) {
    refNotes.push("세트 미등록(플레이트 없음)");
  }
  const anchor = (payload0.styleAnchor && typeof payload0.styleAnchor === "object" && payload0.styleAnchor.objectName) ? payload0.styleAnchor : null;
  // 스타일 기준은 세트 플레이트가 없을 때만 — 플레이트가 이미 그림체를 담고 있고, 다른 방을 찍은 옛 기준 이미지가 붙으면
  // 모델이 그 방(가구·벽지)을 베껴 플레이트와 충돌한다(2026-09-14 소녀의 방: 부감은 분홍 줄무늬·책상, 스틸은 옛 시트의 노란 벽·침대).
  const hasPlateRef = refs.some((r) => r.role === "plate");
  if (anchor && bucket && !hasPlateRef && refs.length < 12) { refs.push({ role: "style", imageUrl: gsOf(anchor.objectName), referenceId: refs.length + 1, referenceKind: "style", subjectDescription: `STYLE ANCHOR — the project's approved style image (${String(anchor.setName || "")})` }); refNotes.push("스타일 기준"); }
  // 전송 순서 = 승인 콘티 → 부감 마스터/레거시 플레이트 → 캐릭터 → (스타일).
  // 콘티가 있으면 구도를 먼저 잠그고 부감은 공간 배치만 보강한다.
  const ROLE_ORDER: Record<string, number> = { storyboard: 0, plate: 1, character: 2, master: 3, style: 4 };
  const orderedRefs = refs
    .map((r, i) => ({ r, i }))
    .sort((a, b) => ((ROLE_ORDER[a.r.role] ?? 9) - (ROLE_ORDER[b.r.role] ?? 9)) || (a.i - b.i))
    .map(({ r }, i) => { const { role, ...rest } = r; void role; return { ...rest, referenceId: i + 1 }; });
  // 작성기 설정(모델·크기)을 그대로 넘긴다 — 스튜디오 버튼과 같은 경로.
  const img = await runImagenTool({
    prompt: promptSent, aspectRatio: input?.aspectRatio || "16:9", projectId,
    _imageStageKey: `scene_still:${projectId}:${scene?.id ?? idx}`,
    ...(orderedRefs.length ? { referenceImages: orderedRefs } : {}),
    ...(input?.provider ? { provider: String(input.provider) } : {}),
    ...(input?.imageSize ? { imageSize: String(input.imageSize) } : {}),
  }, ctx);
  const ref = (img.objectName && bucket) ? `gs://${bucket}/${img.objectName}` : (img.signedUrl || "");
  if (!ref) throw new Error("이미지 생성 결과에 저장할 URL이 없어요.");
  // 이전 이미지는 버전 이력에 보존(되돌리기용). data: 는 영속 금지(OOM 전례) → https/gs 만 보관, 최근 10개.
  const prevImg = String(scene?.imageDataUrl || "").trim();
  let imageHistory: string[] = Array.isArray(scene?.imageHistory) ? scene.imageHistory.filter((v: any) => typeof v === "string" && v) : [];
  if (prevImg && prevImg !== ref && /^(https?:\/\/|gs:\/\/)/i.test(prevImg)) {
    imageHistory.push(prevImg);
    if (imageHistory.length > 10) imageHistory = imageHistory.slice(imageHistory.length - 10);
  }
  // 프롬프트 계보: 이 이미지가 실제로 어떤 최종 프롬프트에서 나왔는지(노드 캔버스가 그린다).
  const prevLineage = (scene?.lineage && typeof scene.lineage === "object") ? scene.lineage : {};
  const lineage = {
    ...prevLineage,
    imagePrompt: promptSent,
    imagePlate: plateVariant,
    imageRefs: refNotes.join(" · "),
    imageAttempts: (Number(prevLineage.imageAttempts) || 0) + 1,
    agentJobId: String(ctx.jobId || ""),
    updatedAt: new Date().toISOString(),
  };
  // 이 잡 안에서 플레이트를 파생했으면 episodeLocations 가 바뀌어 있다 — 최신 씬 목록을 다시 읽어 덮어쓰지 않게 한다.
  const latest = await runProjectGetTool({ projectId }, ctx).catch(() => null);
  const scenesLatest: any[] = Array.isArray(latest?.scenes) && latest.scenes.length === scenes.length ? latest.scenes : scenes;
  scenesLatest[idx] = { ...(scenesLatest[idx] || scene), imageDataUrl: ref, imageHistory, lineage };
  await callInternalJson(ctx, "/api/project/save", { body: { projectId, scenes: scenesLatest } });
  return {
    kind: "scene_still", projectId, sceneId: scene?.id,
    signedUrl: img.signedUrl || "", objectName: img.objectName || "",
    referenceCount: orderedRefs.length, references: refNotes, plateVariant,
    storyboardRef: conti,
    saved: true, promptEcho: promptSent,
  };
}

/** 에이전트 모드(video_pipeline): 프로젝트의 빈 컷을 스틸→영상 순으로 채우는 SkillJob 을 만든다.
 *  인포그래픽 도구와 같은 경로(공통 SkillJob API, wait=1)로 계획·비용 게이트까지 돌고 승인 대기 상태로 돌아온다. */
async function runVideoPipelineTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!projectId) throw new Error("projectId 가 필요해요. project_list 로 확인한 뒤 다시 실행하세요.");
  const stages = Array.isArray(input?.stages) ? input.stages.map((s: any) => String(s)) : ["still", "video"];
  const sceneIds = Array.isArray(input?.sceneIds) ? input.sceneIds.map((s: any) => String(s)) : [];
  const data = await callInternalJson(ctx, "/api/agent/skills/video_pipeline/jobs?wait=1", {
    body: {
      invocationMode: "agent",
      request: String(input?.request || `${projectId} 에이전트 모드 (${stages.join("→")})`),
      conversationId: ctx.conversationId || "main",
      options: {
        projectId, stages, sceneIds,
        aspectRatio: input?.aspectRatio || "",
        videoModel: input?.videoModel || input?.model || "",
        regenerate: input?.regenerate === true,
        maxScenesPerRun: Number(input?.maxScenesPerRun) || 3,
      },
      costControl: { maxAmountUsd: 0 },
    },
  });
  const job = data?.job || {};
  const plan = job?.executionPlan || {};
  const summary = plan?.summary || {};
  return {
    kind: "video_pipeline",
    skillJobId: String(job?.id || ""),
    status: String(job?.status || ""),
    approvalPending: job?.approvalState?.status === "pending",
    plan: summary,
    projectId,
    message: job?.approvalState?.status === "pending"
      ? `계획 완료: 스틸 ${summary.pendingStills ?? 0}개 · 영상 ${summary.pendingVideos ?? 0}개, 예상 ${summary.credits ?? 0} 크레딧. 제작 캔버스의 에이전트 모드 패널에서 승인하면 생성이 시작돼요.`
      : `파이프라인 상태: ${job?.status || "?"}`,
  };
}

/** 씬 영상: video 생성 → 해당 scene.videoUrl 에 부착 후 project_save. 쓰기 → 승인 게이트.
 *  image-to-video 소스: 입력 imageUrl(https) > 씬 스틸(gs:// 또는 https). gs:// 는 /api/video 가
 *  자체 서명(signIfGs / toKlingImageField)하므로 여기서 따로 서명하지 않고 그대로 넘긴다. */
async function runSceneVideoTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!projectId) throw new Error("projectId is required");
  const cur = await runProjectGetTool({ projectId }, ctx);
  const scenes: any[] = Array.isArray(cur.scenes) ? cur.scenes : [];
  if (!scenes.length) throw new Error("프로젝트에 컷이 없어요. scenario_to_project 로 시나리오를 저장하거나, scene_upsert 로 컷을 하나 만들고 다시 부르세요(사용자에게는 캔버스 '컷 추가' 버튼도 있어요).");
  const idx = findSceneIndex(scenes, input?.sceneId ?? input?.scene ?? input?.sceneIndex);
  if (idx < 0) throw new Error(`씬을 찾지 못했어요(sceneId=${input?.sceneId ?? input?.scene ?? "?"}).`);
  const scene = scenes[idx];
  // 프롬프트는 브라우저 pipeline-video 의 promptBase 와 같은 조립기로(명시 prompt 가 오면 그것이 우선).
  const header = String(cur.payload?.header || cur.header || "");
  const prompt = String(input?.prompt || "").trim() || buildSceneVideoPrompt(scene, header, cur.payload || {});
  if (!prompt) throw new Error("영상 프롬프트가 없어요(prompt 또는 씬 비주얼 필요).");
  // i2v 소스 결정: 명시 https > 씬 스틸(imageDataUrl/imagePath — gs:// 또는 https). data: 는 쓰지 않는다.
  const inputImage = String(input?.imageUrl || "").trim();
  const sceneImage = String(scene?.imageDataUrl || scene?.imagePath || "").trim();
  const videoFromImage = /^https?:\/\//i.test(inputImage)
    ? inputImage
    : (/^(https?:\/\/|gs:\/\/)/i.test(sceneImage) ? sceneImage : "");
  // 스튜디오 버튼과 같은 파라미터를 넘긴다: 모델(파이프라인 옵션) · 길이(컷의 estSec) · 음성 플래그(payload).
  const payload0: any = cur.payload || {};
  const toBoolFlag = (v: any, fb: boolean) => (typeof v === "boolean" ? v : (v == null ? fb : String(v).toLowerCase() === "true"));
  const videoModel = String(input?.videoModel || input?.model || payload0.videoModel || "").trim();
  // ★참조→영상 모델이면 스틸 한 장만 보내지 않는다. 시장조사(2026-09-14) 결론: 일관성은 매 호출에 같은 참조 묶음을 붙이는 데서 나온다.
  //   묶음 = [첫 프레임(스틸)] → 세트 플레이트(방위×높이) → 캐릭터 시트(최대 2장씩) → 부감 마스터 → 직전 컷(연속성).
  //   Seedance 2.5 는 직전 컷의 클립을 reference_videos 로, 나머지는 직전 컷 스틸을 이미지로 잇는다. 프롬프트에 순서 매니페스트를 붙인다.
  const REFS_VIDEO_MODELS = ["seedance-2.5", "seedance-r2v", "grok-r2v", "vidu-q3", "wan"];
  const REF_CAPS: Record<string, number> = { "seedance-2.5": 30, "seedance-r2v": 9, "grok-r2v": 7, "vidu-q3": 4, "wan": 4 };
  let referenceImages: string[] = [];
  let referenceVideos: string[] = [];
  const videoRefNotes: string[] = [];
  let promptForVideo = prompt;
  if (REFS_VIDEO_MODELS.includes(videoModel)) {
    const bucket = studioBucket(ctx);
    const gsOf = (obj: any) => `gs://${bucket}/${String(obj || "").replace(/^gs:\/\/[^/]+\//, "")}`;
    const entries: Array<{ url: string; line: string }> = [];
    const startInRefs = videoModel === "seedance-2.5" || videoModel === "seedance-r2v";
    if (startInRefs && videoFromImage) entries.push({ url: videoFromImage, line: "the exact FIRST FRAME of this shot — keep its composition, character placement and framing at t=0" });
    const direction = normalizeCameraDirection(scene?.cameraDirection) || "front";
    const elevation = normalizeCameraElevation(scene?.cameraElevation) || "eye";
    const locations: any[] = Array.isArray(payload0.episodeLocations) ? payload0.episodeLocations : [];
    const locName = String(scene?.sceneLocation || scene?.location || "").trim() || (locations.length === 1 ? String(locations[0]?.name || "") : "");
    const loc: any = locName ? (locations.find((l: any) => normLocationKey(l?.name) === normLocationKey(locName) || normLocationKey(l?.id) === normLocationKey(locName)) || null) : null;
    assertSetPlateReady(loc, input);
    if (loc && bucket) {
      const plate = findPlate(loc, direction, elevation);
      const setName = String(loc.name || locName);
      if (plate) {
        entries.push({ url: gsOf(plate.objectName), line: plate.exact
          ? `the empty SET PLATE of ${setName} for this camera (${plateLabel(direction, elevation, "en")}) — keep its layout, architecture, materials, colors and lighting as the environment of the whole shot`
          : `the TOP-DOWN MASTER PLATE of ${setName} — layout truth; keep every object on the same wall and position` });
        videoRefNotes.push(plate.exact ? `플레이트 ${plateLabel(direction, elevation, "ko")}` : "부감 마스터(플레이트 없음)");
        const master = masterOf(loc);
        if (plate.exact && master && plate.objectName !== master) { entries.push({ url: gsOf(master), line: `the TOP-DOWN MASTER PLATE of ${setName} — layout truth (where each piece of furniture stands); never copy its top-down camera` }); videoRefNotes.push("부감 마스터"); }
      }
    }
    const chars = await collectCharacterRefs(scene, payload0, ctx);
    for (const r of chars.refs) entries.push({ url: String(r.imageUrl), line: `the registered character reference for ${String(r.subjectDescription)} — keep that character's design, face, silhouette, colors and proportions; do not copy its pose, crop or background` });
    if (chars.note) videoRefNotes.push(chars.note);
    // 연속성: 같은 세트의 직전 컷. 2.5 는 클립 자체를, 나머지는 그 컷의 스틸을 룩 참조로.
    const thisLocKey = normLocationKey(locName);
    let prev: any = null;
    for (let k = idx - 1; k >= 0; k--) { const c = scenes[k]; if (c && normLocationKey(String(c?.sceneLocation || c?.location || "")) === thisLocKey) { prev = c; break; } }
    const prevClip = String(prev?.videoUrl || prev?.videoPath || "").trim();
    const prevStill = String(prev?.imageDataUrl || prev?.imagePath || "").trim();
    if (videoModel === "seedance-2.5" && prevClip && /^(https?:\/\/|gs:\/\/)/i.test(prevClip)) { referenceVideos = [prevClip]; videoRefNotes.push(`직전 컷 ${String(prev?.id ?? "")} 클립(연속성)`); }
    else if (prevStill && /^(https?:\/\/|gs:\/\/)/i.test(prevStill)) { entries.push({ url: prevStill, line: `the previous shot of this scene (continuity) — reuse its look, lighting and character designs only; do NOT copy its camera, framing or action` }); videoRefNotes.push(`직전 컷 ${String(prev?.id ?? "")} 스틸(연속성)`); }
    const cap = REF_CAPS[videoModel] || 9;
    const kept = entries.slice(0, cap);
    referenceImages = kept.map((e) => e.url);
    const manifest = kept.length ? ["The input images are provided in this exact order:", ...kept.map((e, i) => `Image ${i + 1}: ${e.line}.`)] : [];
    if (referenceVideos.length) manifest.push(`Video 1: the previous shot of this scene — continue its look, lighting and character designs; do NOT copy its camera or action.`);
    const paletteLock = kept.length ? "PALETTE LOCK: use only the colors, materials and background treatment of the reference images. Do not introduce new colors, do not restyle the characters or the set." : "";
    promptForVideo = [prompt, chars.block, ...manifest, paletteLock].filter(Boolean).join("\n");
    if (entries.length > cap) videoRefNotes.push(`참조 ${entries.length - cap}장 상한 초과로 생략`);
  }
  const sub = await submitVideoJob({
    prompt: promptForVideo,
    imageUrl: videoFromImage || undefined,
    aspectRatio: input?.aspectRatio || payload0.aspectRatio || "16:9",
    videoModel: videoModel || undefined,
    ...(referenceImages.length ? { referenceImages } : {}),
    ...(referenceVideos.length ? { referenceVideos } : {}),
    resolution: String(input?.resolution || "").trim() || undefined,
    durationSeconds: Number(input?.durationSeconds || input?.duration || scene?.estSec) > 0
      ? Number(input?.durationSeconds || input?.duration || scene?.estSec)
      : undefined,
    projectId,
    sceneId: scene?.id,
    narrationEnabled: toBoolFlag(payload0.narrationEnabled, false),
    dubbingEnabled: toBoolFlag(payload0.dubbingEnabled, false),
  }, ctx);
  // 제출만 하고 돌아온다. 완료되면 reconcileVideoJobs 가 attachSceneVideo 로 이 컷에 붙여 저장한다.
  return throwPendingVideo(sub, {
    projectId, sceneId: scene?.id, promptForVideo, videoFromImage, videoRefNotes,
    referenceCount: referenceImages.length + referenceVideos.length, agentJobId: String(ctx.jobId || ""),
  });
}

/** 완성된 영상을 컷에 부착·저장(scene_video 의 뒷부분). 완료 시점의 프로젝트를 다시 읽어 다른 컷의 변경을 덮지 않는다. */
export async function attachSceneVideo(ctx: ToolContext, attach: SceneVideoAttach, videoUrl: string): Promise<any> {
  const ref = String(videoUrl || "").trim();
  if (!ref) throw new Error("영상 생성 결과 URL이 없어요.");
  const projectId = String(attach?.projectId || "").trim();
  if (!projectId) throw new Error("projectId is required");
  const cur = await runProjectGetTool({ projectId }, ctx);
  const scenes: any[] = Array.isArray(cur.scenes) ? cur.scenes : [];
  const idx = findSceneIndex(scenes, attach.sceneId);
  if (idx < 0) throw new Error(`씬을 찾지 못했어요(sceneId=${attach.sceneId ?? "?"}).`);
  const scene = scenes[idx];
  const videoRefNotes = Array.isArray(attach.videoRefNotes) ? attach.videoRefNotes : [];
  // 프롬프트 계보: 어떤 프롬프트·어떤 스틸에서 이 영상이 나왔는지(노드 캔버스가 그린다).
  const prevLineage = (scene?.lineage && typeof scene.lineage === "object") ? scene.lineage : {};
  const lineage = {
    ...prevLineage,
    videoPrompt: attach.promptForVideo,
    videoFromImage: attach.videoFromImage,
    videoRefs: videoRefNotes.join(" · "),
    videoAttempts: (Number(prevLineage.videoAttempts) || 0) + 1,
    agentJobId: String(attach.agentJobId || ctx.jobId || ""),
    updatedAt: new Date().toISOString(),
  };
  scenes[idx] = { ...scene, videoUrl: ref, lineage };
  await callInternalJson(ctx, "/api/project/save", { body: { projectId, scenes } });
  return { kind: "scene_video", projectId, sceneId: scene?.id, videoUrl: ref, videoFromImage: attach.videoFromImage, referenceCount: Number(attach.referenceCount) || 0, references: videoRefNotes, saved: true, promptEcho: attach.promptForVideo };
}

// ────────────────────────────────────────────────────────────────────────────
// STEP 2 (P2) — 렌더링·다운로드 + 사운드/편집 확장.
// 디테일 편집설정은 보류(기본값). 최종 렌더·다운로드는 반드시 가능하도록.
// ────────────────────────────────────────────────────────────────────────────

/** 최종 렌더링(제출-only): /api/postprod/transcode 에 제출하고 즉시 반환(폴링하지 않음 — 게이트/CF 응답 블로킹 방지).
 *  다중 씬 concat: sources[](또는 sourceObjectNames[]) 여러 개면 순서대로 이어붙여 렌더. 단일 sourceObjectName 도 허용.
 *  완료는 status 폴링(statusUrl) 또는 렌더가 끝나면 유효해지는 downloadUrl(프록시)로 확인. */
async function runRenderFinalTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || input?.id || "").trim();
  const multi: any[] = Array.isArray(input?.sources) ? input.sources
    : (Array.isArray(input?.sourceObjectNames) ? input.sourceObjectNames : []);
  const sourceObjectNames = multi.map((v) => String(v || "").trim()).filter(Boolean);
  const single = String(input?.sourceObjectName || input?.source || "").trim();
  if (!projectId || (!sourceObjectNames.length && !single)) {
    throw new Error("projectId 와 소스 영상(sources[] 또는 sourceObjectName)이 필요해요.");
  }
  const body: any = {
    projectId,
    aspectRatio: String(input?.aspectRatio || "16:9"),
    sourceDurationSec: Number(input?.sourceDurationSec || 0),
  };
  if (sourceObjectNames.length) body.sourceObjectNames = sourceObjectNames;
  else body.sourceObjectName = single;
  const sub = await callInternalJson(ctx, "/api/postprod/transcode", { body });
  const jobName = String(sub?.jobName || "").trim();
  const outputObjectName = String(sub?.outputObjectName || "").trim();
  if (!jobName || !outputObjectName) throw new Error("트랜스코드 잡 생성 응답이 올바르지 않아요.");
  const token = ctx.authHeader.replace(/^Bearer\s+/i, "").trim();
  const base = new URL(ctx.request.url).origin;
  const downloadUrl = `${base}/api/media/proxy?objectName=${encodeURIComponent(outputObjectName)}${token ? `&token=${encodeURIComponent(token)}` : ""}`;
  const statusUrl = `${base}/api/postprod/transcode/status?jobName=${encodeURIComponent(jobName)}&outputObjectName=${encodeURIComponent(outputObjectName)}`;
  return {
    kind: "render_final", projectId, status: "processing",
    sourceCount: sourceObjectNames.length || 1,
    jobName, outputObjectName, downloadUrl, statusUrl,
    note: "렌더링을 시작했어요(수분 소요). 완료되면 위 다운로드 링크가 유효해져요.",
  };
}

/** 다운로드 링크 제공: 라이브러리 signedUrl 재사용 또는 objectName→미디어 프록시 URL(+token). read. */
async function runAssetDownloadTool(input: any, ctx: ToolContext): Promise<any> {
  const signedUrl = String(input?.signedUrl || input?.url || "").trim();
  const objectName = String(input?.objectName || "").trim();
  if (/^https?:\/\//i.test(signedUrl)) {
    return { kind: "asset_download", downloadUrl: signedUrl, via: "signedUrl", objectName: objectName || undefined };
  }
  if (!objectName) throw new Error("objectName 또는 signedUrl 중 하나가 필요해요.");
  const token = ctx.authHeader.replace(/^Bearer\s+/i, "").trim();
  const base = new URL(ctx.request.url).origin;
  const downloadUrl = `${base}/api/media/proxy?objectName=${encodeURIComponent(objectName)}${token ? `&token=${encodeURIComponent(token)}` : ""}`;
  return { kind: "asset_download", downloadUrl, via: "proxy", objectName };
}

/** 캐릭터별 더빙/음성: /api/sound/voice-generate (ElevenLabs 세그먼트). segments 또는 text 단일. external. */
async function runVoiceGenerateTool(input: any, ctx: ToolContext): Promise<any> {
  let segments: any[] = Array.isArray(input?.segments) ? input.segments : [];
  if (!segments.length) {
    const text = String(input?.text || input?.script || input?.prompt || "").trim();
    if (text) segments = [{ text, voiceId: input?.voiceId, providerVoiceId: input?.providerVoiceId, speaker: input?.speaker }];
  }
  segments = segments
    .map((s) => ({
      text: String(s?.text || "").trim(),
      voiceId: String(s?.voiceId || "").trim() || undefined,
      providerVoiceId: String(s?.providerVoiceId || "").trim() || undefined,
      speaker: String(s?.speaker || "").trim() || undefined,
    }))
    .filter((s) => s.text);
  if (!segments.length) throw new Error("더빙할 대사(segments 또는 text)가 필요해요.");
  const data = await callInternalJson(ctx, "/api/sound/voice-generate", {
    body: {
      segments,
      mode: input?.mode === "project" ? "project" : "instance",
      brandId: input?.brandId ? String(input.brandId) : undefined,
      episodeId: input?.episodeId ? String(input.episodeId) : undefined,
      sessionId: String(input?.sessionId || "ai-company"),
      model: input?.model ? String(input.model) : undefined,
      format: input?.format ? String(input.format) : undefined,
    },
  });
  return { kind: "audio", audioUrl: data?.outputUrl || "", assetId: data?.assetId || "", creditsUsed: data?.creditsUsed, model: "elevenlabs", segments: segments.length };
}

/** 사용 가능한 목소리 목록: /api/voices(ElevenLabs) 또는 /api/tts/voices(Google). read. */
async function runVoicesListTool(input: any, ctx: ToolContext): Promise<any> {
  const src = String(input?.source || "").trim().toLowerCase();
  const google = src === "tts" || src === "google";
  const path = google ? "/api/tts/voices" : "/api/voices";
  const qs: string[] = [];
  if (input?.gender) qs.push(`gender=${encodeURIComponent(String(input.gender))}`);
  if (input?.q) qs.push(`q=${encodeURIComponent(String(input.q))}`);
  if (input?.brandId) qs.push(`brandId=${encodeURIComponent(String(input.brandId))}`);
  const data = await callInternalJson(ctx, `${path}${qs.length ? `?${qs.join("&")}` : ""}`);
  const voices = (Array.isArray(data?.voices) ? data.voices : []).slice(0, 60);
  return { kind: "voices_list", source: google ? "google-tts" : "elevenlabs", count: voices.length, voices };
}

/** 사운드 자산 목록: /api/sound/assets. read. */
async function runSoundAssetsTool(input: any, ctx: ToolContext): Promise<any> {
  const qs: string[] = [];
  for (const k of ["scope", "brandId", "episodeId", "sessionId", "type"]) {
    if (input?.[k]) qs.push(`${k}=${encodeURIComponent(String(input[k]))}`);
  }
  const data = await callInternalJson(ctx, `/api/sound/assets${qs.length ? `?${qs.join("&")}` : ""}`);
  const assets = (Array.isArray(data?.assets) ? data.assets : []).slice(0, 40);
  return { kind: "sound_assets", count: assets.length, assets };
}

/** 씬 → 샷 분해: /api/scenario-shots. projectId(씬 로드) 또는 scenes 직접. external(검수 패널). */
async function runSceneShotsTool(input: any, ctx: ToolContext): Promise<any> {
  let scenes: any[] = Array.isArray(input?.scenes) ? input.scenes : [];
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!scenes.length && projectId) {
    const cur = await runProjectGetTool({ projectId }, ctx);
    scenes = Array.isArray(cur.scenes) ? cur.scenes : [];
  }
  if (!scenes.length) throw new Error("샷으로 분해할 씬이 없어요(projectId 또는 scenes 필요).");
  const data = await callInternalJson(ctx, "/api/scenario-shots", { body: { scenes, language: input?.language === "en" ? "en" : "ko" } });
  const out = Array.isArray(data?.scenes) ? data.scenes : [];
  return { kind: "scene_shots", projectId: projectId || undefined, sceneCount: out.length, scenes: out, meta: data?.meta };
}

/** 씬 장소 추출: /api/scenario/locations. read+synthesize. */
async function runSceneLocationsTool(input: any, ctx: ToolContext): Promise<any> {
  let scenes: any[] = Array.isArray(input?.scenes) ? input.scenes : [];
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!scenes.length && projectId) {
    const cur = await runProjectGetTool({ projectId }, ctx);
    scenes = Array.isArray(cur.scenes) ? cur.scenes : [];
  }
  if (!scenes.length) throw new Error("장소를 뽑을 씬이 없어요(projectId 또는 scenes 필요).");
  const data = await callInternalJson(ctx, "/api/scenario/locations", { body: { scenes, language: input?.language === "en" ? "en" : "ko" } });
  return { kind: "scene_locations", locations: Array.isArray(data?.locations) ? data.locations : [] };
}

/** 스토리 구조 생성: /api/story-structure. read+synthesize. */
async function runStoryStructureTool(input: any, ctx: ToolContext): Promise<any> {
  const topic = String(input?.topic || input?.story || input?.prompt || "").trim();
  if (!topic) throw new Error("스토리 구조를 짤 주제(topic)가 필요해요.");
  const data = await callInternalJson(ctx, "/api/story-structure", {
    body: {
      topic, story: String(input?.story || topic), duration: String(input?.duration || "60"),
      target: input?.target || input?.targetAudience,
      tones: Array.isArray(input?.tones) ? input.tones : (input?.tones ? [input.tones] : []),
      styles: Array.isArray(input?.styles) ? input.styles : (input?.styles ? [input.styles] : []),
      characters: Array.isArray(input?.characters) ? input.characters : [],
    },
  });
  return { kind: "story_structure", story: data?.story || "", beats: Array.isArray(data?.beats) ? data.beats : [] };
}

/** 씬 수정/추가: project_get → 해당 씬 병합 수정(없으면 추가) → project_save. 쓰기 → 승인 게이트. */
async function runSceneUpsertTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!projectId) throw new Error("projectId is required");
  const cur = await runProjectGetTool({ projectId }, ctx);
  const scenes: any[] = Array.isArray(cur.scenes) ? cur.scenes.slice() : [];
  const patch: Record<string, any> = (input?.scene && typeof input.scene === "object") ? { ...input.scene } : {};
  // common/promptText/promptEdited/cameraDirection/beats/blocking/cutRef* 는 캔버스·채팅이 프롬프트와
  // 컷↔컷 참조선을 편집하는 필드 — 여기 없으면 에이전트가 고쳐도 저장 전에 증발한다.
  const FIELDS = ["title", "lines", "narration", "dialogue", "sceneLocation", "backgroundStyle", "subtitleText", "videoSpeechPrompt", "script", "visual", "shot", "shotType", "cameraMove", "composition", "action", "estSec",
    "common", "promptText", "promptEdited", "cameraDirection", "cameraElevation", "beats", "blocking", "cutRefId", "cutRefEnabled", "sceneBreak",
    // 이미 만들어 둔 산출물을 컷에 붙이는 필드(저장 경로). save 가 gs:// 로 정규화한다.
    "imagePath", "imageDataUrl", "videoUrl"];
  for (const f of FIELDS) if (input?.[f] !== undefined && patch[f] === undefined) patch[f] = input[f];
  // 지목한 산출물(jobId)·저장 경로(objectName)를 컷의 스틸/영상으로 부착. "이 이미지와 영상을 에피소드에 넣어줘" 가 통하게.
  const bucketForAssets = studioBucket(ctx);
  const gsFor = (objectName: string) => {
    const plain = String(objectName || "").replace(/^gs:\/\/[^/]+\//, "");
    if (!plain) return "";
    if (!bucketForAssets) throw new Error("이미지 저장소 버킷이 설정되지 않아 산출물을 컷에 붙일 수 없어요.");
    return `gs://${bucketForAssets}/${plain}`;
  };
  const assetFromJob = async (jobId: string): Promise<string> => {
    const sql = getSql(ctx.env);
    const job: any = sql ? await getJob(sql, jobId, ctx.userId).catch(() => null) : null;
    const out: any = job?.output && typeof job.output === "object" ? job.output : {};
    const objectName = String(out.objectName || "").trim() || mediaObjectNameFromUrl(String(out.videoUrl || out.signedUrl || ""));
    if (!objectName) throw new Error(`jobId ${jobId.slice(0, 8)} 에서 산출물 저장 경로를 찾지 못했어요.`);
    return gsFor(objectName);
  };
  const stillJob = String(input?.stillJobId || input?.imageJobId || "").trim();
  const videoJob = String(input?.videoJobId || "").trim();
  const stillObj = String(input?.imageObjectName || input?.stillObjectName || "").trim();
  const videoObj = String(input?.videoObjectName || "").trim();
  if (stillJob) { const gs = await assetFromJob(stillJob); patch.imagePath = gs; patch.imageDataUrl = gs; }
  else if (stillObj) { const gs = gsFor(stillObj); patch.imagePath = gs; patch.imageDataUrl = gs; }
  if (videoJob) patch.videoUrl = await assetFromJob(videoJob);
  else if (videoObj) patch.videoUrl = gsFor(videoObj);
  delete patch.id; // id는 매칭·부여 전용, 병합 대상 아님
  const ref = input?.sceneId ?? input?.scene?.id ?? input?.sceneIndex;
  const idx = findSceneIndex(scenes, ref);
  let targetId: any;
  let mode: string;
  if (idx >= 0) {
    scenes[idx] = { ...scenes[idx], ...patch };
    targetId = scenes[idx].id;
    mode = "update";
  } else {
    if (Object.keys(patch).length === 0) throw new Error("씬을 찾지 못했고, 추가할 내용도 없어요.");
    const newId = scenes.length ? Math.max(...scenes.map((s) => Number(s?.id) || 0)) + 1 : 1;
    scenes.push({ id: newId, ...patch });
    targetId = newId;
    mode = "add";
  }
  const saved = await callInternalJson(ctx, "/api/project/save", { body: { projectId, scenes } });
  return { kind: "scene_upsert", projectId, sceneId: targetId, mode, sceneCount: scenes.length, saved: true, objectName: saved?.objectName || "" };
}

/** 컷 순서 변경: project_get → order(컷 id 순열)대로 scenes 재배열(id 불변) → 경고 검사 → project_save. 쓰기 → 승인 게이트.
 *  제작 캔버스가 컷 카드를 다른 칸에 놓으면 이 도구로 실제 순서를 바꾼다(배치 canvasLayout 은 표시용).
 *  경고(set-crossing: 세트 묶음을 넘어감 / song-section: 노래 구간 어긋남)는 막지 않고 결과에 실어 돌려준다. */
async function runSceneReorderTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!projectId) throw new Error("projectId is required");
  const order: any[] = Array.isArray(input?.order) ? input.order : (Array.isArray(input?.sceneIds) ? input.sceneIds : []);
  if (!order.length) throw new Error("order(컷 id 순열)가 필요해요");
  const cur = await runProjectGetTool({ projectId }, ctx);
  const scenes: any[] = Array.isArray(cur.scenes) ? cur.scenes.slice() : [];
  const applied = applySceneOrder(scenes, order);
  if (!applied.ok) throw new Error(applied.error);
  const warnings = analyzeReorder(scenes, applied.scenes, cur.payload || {});
  if (!applied.moved.length) {
    return { kind: "scene_reorder", projectId, changed: false, moved: [], warnings, summary: "순서가 그대로예요", saved: false };
  }
  const saved = await callInternalJson(ctx, "/api/project/save", { body: { projectId, scenes: applied.scenes } });
  return {
    kind: "scene_reorder", projectId, changed: true, moved: applied.moved,
    order: applied.scenes.map((s, i) => String(s?.id ?? i + 1)),
    warnings, summary: summarizeWarnings(warnings) || "경고 없음",
    sceneCount: applied.scenes.length, saved: true, objectName: saved?.objectName || "",
  };
}

/** 장소 이름 정규화(set-plates.findLocationForScene 과 같은 느슨한 비교). */
function normLocationKey(v: any): string {
  return locationKey(v);
}

/** 장소 합치기: from 장소의 컷을 into 로 옮기고(sceneLocation 재작성), episodeLocations·storyboardSheets 도 into 로 모은다.
 *  세트의 정체성이 문자열이라 같은 방이 두 이름으로 갈려 각각 따로 생성되던 문제(2026-09-13 "소녀의 방" 2벌)의 수습 도구.
 *  into 에 플레이트·시트가 없으면 from 것을 물려받는다. 컷 id 는 그대로. 쓰기 → 게이트(캔버스는 자동 승인). */
async function runLocationMergeTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!projectId) throw new Error("projectId is required");
  const from = String(input?.from || input?.fromName || "").trim();
  const into = String(input?.into || input?.intoName || "").trim();
  if (!from || !into) throw new Error("from(합칠 장소)과 into(남길 장소)가 필요해요");
  if (normLocationKey(from) === normLocationKey(into)) throw new Error("같은 장소예요");
  const cur = await runProjectGetTool({ projectId }, ctx);
  const scenes: any[] = Array.isArray(cur.scenes) ? cur.scenes : [];
  const payload: any = (cur.payload && typeof cur.payload === "object") ? cur.payload : {};
  const merged = applyLocationMerge(scenes, from, into);
  const locations: any[] = Array.isArray(payload.episodeLocations) ? payload.episodeLocations.map((l: any) => ({ ...l })) : [];
  const fi = locations.findIndex((l) => normLocationKey(l?.name) === normLocationKey(from));
  let ti = locations.findIndex((l) => normLocationKey(l?.name) === normLocationKey(into));
  if (ti < 0) { locations.push({ id: normLocationKey(into).replace(/[^0-9a-z가-힣]+/g, "-").slice(0, 48) || "set", name: into, description: "", refObjectName: "", variants: [] }); ti = locations.length - 1; }
  const target = locations[ti];
  let inherited: string[] = [];
  if (fi >= 0) {
    const src = locations[fi];
    if (!target.refObjectName && src.refObjectName) { target.refObjectName = src.refObjectName; inherited.push("plate"); }
    if (!target.description && src.description) { target.description = src.description; inherited.push("description"); }
    if (!target.setSheet && src.setSheet) { target.setSheet = src.setSheet; inherited.push("setSheet"); }
    const have = new Set((Array.isArray(target.variants) ? target.variants : []).map((v: any) => String(v?.id || "")));
    (Array.isArray(src.variants) ? src.variants : []).forEach((v: any) => { if (v && v.refObjectName && !have.has(String(v.id || ""))) { target.variants = [...(target.variants || []), v]; inherited.push(`variant:${v.id}`); } });
    target.mergedFrom = [...(Array.isArray(target.mergedFrom) ? target.mergedFrom : []), { name: String(src.name || from), at: new Date().toISOString() }];
    locations.splice(fi, 1);
  }
  const sheets: any[] = (Array.isArray(payload.storyboardSheets) ? payload.storyboardSheets : []).map((sh: any) => (
    sh && normLocationKey(sh.setName) === normLocationKey(from) ? { ...sh, setName: into, mergedFromSetName: sh.setName } : sh
  ));
  await callInternalJson(ctx, "/api/project/save", { body: { projectId, scenes: merged.scenes, payload: { episodeLocations: locations, storyboardSheets: sheets } } });
  return { kind: "location_merge", projectId, from, into, cutsMoved: merged.changed, inherited, saved: true, summary: `장소 합치기: "${from}" → "${into}" (컷 ${merged.changed}개 이동${inherited.length ? `, 물려받음: ${inherited.join(", ")}` : ""})` };
}

/** 같은 세트로 보이는 장소 쌍(읽기): 캔버스·채팅이 "합칠까요?" 를 물을 근거. */
async function runLocationSuggestTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!projectId) throw new Error("projectId is required");
  const cur = await runProjectGetTool({ projectId }, ctx);
  const names = (Array.isArray(cur.scenes) ? cur.scenes : []).map((s: any) => String(s?.sceneLocation || s?.location || "").trim()).filter(Boolean);
  const suggestions = suggestLocationMerges(names);
  return { kind: "location_suggest", projectId, suggestions, summary: suggestions.length ? suggestions.map((x: any) => `"${x.from}" → "${x.into}"`).join(", ") : "합칠 장소 없음" };
}

/** 세트 시트(바이블, E2): 장소 하나를 2×2(정면·후면·부감·로우, 인물 없음) 한 장으로 만든다.
 *  캔버스 배경 바의 생성 버튼이 장소마다 이 잡을 하나씩 만든다(이미지 1장 = 30초 한계 안).
 *  결과는 payload.storyboardSheets(kind 'bible-set') + episodeLocations[].setSheet 에 남고, 패널 승인·크롭은 다음 단계.
 *  마스터 플레이트가 있으면 참조로 붙여 1번 칸이 그 플레이트를 따르게 한다. 크레딧을 쓰므로 승인 게이트. */
async function runSetSheetTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!projectId) throw new Error("projectId is required");
  const name = String(input?.locationName || input?.name || input?.setName || "").trim();
  if (!name) throw new Error("locationName(세트 이름)이 필요해요");
  const cur = await runProjectGetTool({ projectId }, ctx);
  const payload: any = (cur.payload && typeof cur.payload === "object") ? cur.payload : {};
  const header = String(payload.header || cur.header || "");
  const aspect = String(input?.aspectRatio || payload.aspectRatio || "16:9");
  const resolution = String(input?.resolution || input?.imageSize || "2K").toUpperCase() === "4K" ? "4K" : "2K";
  const locations: any[] = Array.isArray(payload.episodeLocations) ? payload.episodeLocations.map((l: any) => ({ ...l })) : [];
  const key = normLocationKey(name);
  let idx = locations.findIndex((l) => normLocationKey(l?.name) === key || normLocationKey(l?.id) === key);
  if (idx < 0) {
    locations.push({ id: key.replace(/[^0-9a-z가-힣]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 48) || "set", name, description: "", refObjectName: "", variants: [] });
    idx = locations.length - 1;
  }
  const loc = locations[idx];
  // 장소 칸에 문장이 들어온 프로젝트(옛 데이터)면 그대로 그리지 않는다 — 세트 시트가 엉뚱한 장소가 된다. 핵심 이름만 쓰고 원문은 묘사로 돌린다.
  const rawSetName = String(loc.name || name);
  const promptSetName = looksLikeSentenceLocation(rawSetName) ? (sanitizeSetName(rawSetName) || "the main set") : rawSetName;
  const promptSetDesc = String(loc.description || "").trim() || (looksLikeSentenceLocation(rawSetName) ? rawSetName : "");
  // 브랜드 허브(톤&매너·세계관/배경·스토리·규칙·참조)가 프롬프트의 첫 블록이다. 세트 묘사보다 앞에 둔다.
  const hubContext = buildHubContext(payload);
  const promptInput = { header, hub: hubContext, set: { name: promptSetName, description: promptSetDesc }, aspect, hasStyleRef: false, hasPlateRef: false, nameWasSentence: looksLikeSentenceLocation(rawSetName) };
  const bucket = studioBucket(ctx);
  const gsOf = (obj: any) => `gs://${bucket}/${String(obj || "").replace(/^gs:\/\/[^/]+\//, "")}`;
  const referenceImages: any[] = [];
  // 스타일 앵커: 프로젝트에서 먼저 만든(승인된) 세트 시트 하나가 이후 모든 시트의 "그림체 기준"이다.
  // 참조 이미지가 텍스트 스타일을 이기므로(같은 헤더인데 실사/애니로 갈린 실제 사례) 문장이 아니라 이미지로 고정한다.
  const anchor = (payload.styleAnchor && typeof payload.styleAnchor === "object" && payload.styleAnchor.objectName) ? payload.styleAnchor : null;
  const anchorFromOther = !anchor ? locations.find((l, i) => i !== idx && l?.setSheet?.objectName) : null;
  const styleRef = anchor ? { objectName: String(anchor.objectName), setName: String(anchor.setName || "") } : (anchorFromOther ? { objectName: String(anchorFromOther.setSheet.objectName), setName: String(anchorFromOther.name || "") } : null);
  const useStyleAnchor = input?.useStyleAnchor !== false && !!(styleRef && bucket);
  let styleSource = "";
  if (useStyleAnchor && styleRef) {
    referenceImages.push({ imageUrl: gsOf(styleRef.objectName), referenceId: 1, subjectDescription: `STYLE ANCHOR — the approved set sheet of a DIFFERENT set (${styleRef.setName || "another set"}) in this project`, referenceKind: "style" });
    styleSource = anchor ? "styleAnchor" : "other-set-sheet";
  } else if (input?.useStyleAnchor !== false) {
    // 앵커가 아직 없으면 프로젝트 허브의 기존 이미지가 그림체 기준이다 — 텍스트만으로 그리면 프로젝트와 무관한 룩이 나온다
    // (2026-09-14 실제: 파스텔 실사풍 침실. 컷 생성은 캐릭터 시트를 참조해 원래 룩이 나왔다).
    // 우선순위: ⓪ 허브 배경·소품 자산 이미지(최대 2) ① 브랜드 등록 캐릭터 시트(주 이미지, 최대 2) ② 이 프로젝트의 기존 스틸(최대 1) ③ 기존 정면 플레이트.
    const envAssets: any[] = Array.isArray(payload.environmentAssets) ? payload.environmentAssets : (Array.isArray(payload.knowledgeEnvironmentAssets) ? payload.knowledgeEnvironmentAssets : []);
    for (const ea of envAssets) {
      if (referenceImages.length >= 2) break;
      const url = String(ea?.imageDataUrl || ea?.imageUrl || ea?.refObjectName || ea?.objectName || "").trim();
      if (!url || /^(data:|blob:)/i.test(url)) continue;
      referenceImages.push({ imageUrl: /^(gs:|https?:)/i.test(url) ? url : gsOf(url), referenceId: referenceImages.length + 1, subjectDescription: `STYLE ANCHOR — brand hub environment asset "${String(ea?.name || ea?.label || "environment").slice(0, 60)}" (match rendering style, palette, materials and lighting; do not copy its layout unless it is this set)`, referenceKind: "style" });
    }
    if (referenceImages.length) styleSource = "hub-environment-assets";
    const brandId = String(payload.brandId || payload.brandRef?.id || "").trim();
    if (brandId && referenceImages.length < 2) {
      try {
        const got: any = await runBrandGetTool({ brandId }, ctx);
        const sheets = Array.isArray(got?.brand?.characterSheets) ? got.brand.characterSheets : [];
        for (const entry of sheets) {
          if (referenceImages.length >= 2) break;
          const items = Array.isArray(entry?.items) ? entry.items : [];
          const primary = items.find((it: any) => it?.isPrimary) || items[0];
          const url = String(primary?.imageDataUrl || "").trim();
          if (!url || /^(data:|blob:)/i.test(url)) continue;
          referenceImages.push({ imageUrl: url, referenceId: referenceImages.length + 1, subjectDescription: `STYLE ANCHOR — registered character sheet of ${String(entry?.displayName || entry?.token || "a character").replace(/^@+/, "")} (match the rendering style, palette and lighting ONLY; do NOT draw this character — the set is empty)`, referenceKind: "style" });
        }
        if (referenceImages.length && !styleSource) styleSource = "brand-character-sheets";
      } catch { /* 브랜드를 못 읽으면 다음 후보 */ }
    }
    if (!referenceImages.length) {
      const stills: any[] = Array.isArray(cur.scenes) ? cur.scenes : [];
      const still = stills.map((sc) => String(sc?.imagePath || sc?.imageDataUrl || "").trim()).find((v) => v && !/^(data:|blob:)/i.test(v));
      if (still && bucket) {
        referenceImages.push({ imageUrl: /^(gs:|https?:)/i.test(still) ? still : gsOf(still), referenceId: 1, subjectDescription: "STYLE ANCHOR — an existing still of this project (match the rendering style, palette and lighting ONLY; do NOT copy its characters or composition)", referenceKind: "style" });
        styleSource = "project-still";
      }
    }
    if (!referenceImages.length && loc.refObjectName && bucket) {
      referenceImages.push({ imageUrl: gsOf(loc.refObjectName), referenceId: 1, subjectDescription: `STYLE ANCHOR — the existing front plate of ${String(loc.name || name)} (match the rendering style ONLY)`, referenceKind: "style" });
      styleSource = "existing-plate";
    }
  }
  const hasStyleRefs = referenceImages.some((r) => r.referenceKind === "style");
  // 정면 플레이트 참조는 선택(기본 끔): 옛 플레이트가 다른 그림체면 시트 전체를 그쪽으로 끌고 간다(실제 사례).
  const usePlate = input?.usePlate === true && !!(loc.refObjectName && bucket);
  if (usePlate) {
    referenceImages.push({ imageUrl: gsOf(loc.refObjectName), referenceId: referenceImages.length + 1, subjectDescription: `${String(loc.name || name)} (front-facing master plate)`, referenceKind: "environment" });
  }
  promptInput.hasStyleRef = hasStyleRefs; promptInput.hasPlateRef = usePlate;
  const prompt = String(input?.prompt || "").trim() || buildBibleSetSheetPrompt(promptInput);
  const providerOpt = input?.provider ? { provider: String(input.provider) } : {};
  let img: any;
  let fallback = "";
  let firstError = "";
  try {
    img = await runImagenTool({ prompt, aspectRatio: aspect, projectId, referenceImages, generationMode: "text-to-image", imageSize: resolution, _imageStageKey: `set_sheet:${projectId}:${name}`, ...providerOpt }, ctx);
  } catch (e: any) {
    // 1차 실패: 해상도 지정·플레이트 참조를 빼고 한 번 더. 어느 쪽이 원인인지 결과에 남겨 다음 시도에 쓴다.
    if (e?.subscriptionImage) throw e;
    firstError = String(e?.message || e);
    fallback = "default-size-no-reference";
    try {
      img = await runImagenTool({ prompt, aspectRatio: aspect, projectId, referenceImages: [], generationMode: "text-to-image", _imageStageKey: `set_sheet:${projectId}:${name}:fallback`, ...providerOpt }, ctx);
    } catch (e2: any) {
      throw new Error(`세트 시트 생성 실패 — 1차(${resolution}${referenceImages.length ? "+플레이트 참조" : ""}): ${firstError} / 2차(기본 크기, 참조 없음): ${String(e2?.message || e2)}`);
    }
  }
  if (!img?.objectName) throw new Error("세트 시트 결과에 저장 경로(objectName)가 없어요.");
  const sheetId = `sheet_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 6)}`;
  const sheet = {
    id: sheetId, kind: "bible-set", setId: String(loc.id || ""), setName: String(loc.name || name),
    cutIds: [], resolution: fallback ? "default" : resolution, requestedResolution: resolution, fallback, grid: { cols: 2, rows: 2 }, objectName: img.objectName,
    panels: SET_ANGLES.map((a: any, i: number) => ({ index: i + 1, role: "set", ref: a.id, angleLabel: a.label, objectName: "", status: "pending", label: "bible" })),
    prompt, referenceMeta: { plate: usePlate, styleSource: fallback ? "" : styleSource, hub: !!hubContext }, model: img.model || "", imageSizeApplied: String(img.imageSizeApplied || ""),
    // 어떻게 만들어졌나(비교·검증용): 모델·공급자·경로·참조 수·스타일 참조 출처·허브 블록 여부·프롬프트 앞부분
    diag: {
      provider: String(img.provider || ""), model: String(img.model || ""), geminiEndpoint: String(img.geminiEndpoint || ""), geminiLocationFallback: String(img.geminiLocationFallback || ""),
      referenceCount: fallback ? 0 : Number(img.referenceImageCount) || 0, styleSource: fallback ? "" : styleSource, hubContextUsed: !!hubContext, requestedResolution: resolution, fallback,
      promptHead: String(prompt).slice(0, 1200),
    },
    agentJobId: String(ctx.jobId || ""), createdAt: new Date().toISOString(),
  };
  const sheets: any[] = Array.isArray(payload.storyboardSheets) ? payload.storyboardSheets.slice() : [];
  sheets.push(sheet);
  locations[idx] = { ...loc, setSheet: { sheetId, objectName: img.objectName, resolution: fallback ? "default" : resolution, createdAt: sheet.createdAt, diag: sheet.diag } };
  // 첫 세트 시트가 프로젝트의 스타일 앵커가 된다(없을 때만). 바꾸려면 캔버스에서 다른 시트를 기준으로 지정.
  const nextPayload: any = { episodeLocations: locations, storyboardSheets: sheets };
  if (!anchor) nextPayload.styleAnchor = { objectName: img.objectName, sheetId, setName: String(loc.name || name), createdAt: sheet.createdAt };
  await callInternalJson(ctx, "/api/project/save", { body: { projectId, payload: nextPayload } });
  return {
    kind: "set_sheet", projectId, locationName: String(loc.name || name), sheetId, objectName: img.objectName, signedUrl: img.signedUrl || "",
    resolution: fallback ? "default" : resolution, requestedResolution: resolution, plateReferenced: !fallback && usePlate, styleAnchored: !fallback && hasStyleRefs, styleSource: fallback ? "" : styleSource, hubContextUsed: !!hubContext, styleAnchorSet: styleRef ? styleRef.setName : "", becameStyleAnchor: !anchor, model: img.model || "", saved: true, promptEcho: prompt,
    fallback, firstError,
    summary: `세트 시트(${fallback ? "기본 크기·참조 없음으로 재시도" : resolution}) 생성: ${String(loc.name || name)} — 정면·후면·부감·로우 4칸. 패널 승인은 캔버스 배경 카드에서.${firstError ? ` (1차 실패: ${firstError.slice(0, 120)})` : ""}`,
  };
}

/** 세트 플레이트용 그림체(style) 참조 수집 — set_sheet 와 같은 우선순위: 스타일 앵커 → 다른 세트 시트/마스터 → 허브 배경·소품 자산 → 브랜드 캐릭터 시트(그림체만) → 기존 스틸. */
async function collectStyleRefs(payload: any, locations: any[], idx: number, cur: any, bucket: string, ctx: ToolContext, max = 2): Promise<{ refs: any[]; source: string }> {
  const gsOf = (obj: any) => `gs://${bucket}/${String(obj || "").replace(/^gs:\/\/[^/]+\//, "")}`;
  const refs: any[] = [];
  const anchor = (payload.styleAnchor && typeof payload.styleAnchor === "object" && payload.styleAnchor.objectName) ? payload.styleAnchor : null;
  if (anchor && bucket) { refs.push({ imageUrl: gsOf(anchor.objectName), referenceId: 1, subjectDescription: `STYLE ANCHOR — the project's approved style image (${String(anchor.setName || "")})`, referenceKind: "style" }); return { refs, source: "styleAnchor" }; }
  const other = locations.find((l, i) => i !== idx && (l?.setSheet?.objectName || (Array.isArray(l?.variants) && l.variants.find((v: any) => v?.id === "angle-top" && v?.refObjectName))));
  if (other && bucket) {
    const obj = other.setSheet?.objectName || other.variants.find((v: any) => v?.id === "angle-top")?.refObjectName;
    refs.push({ imageUrl: gsOf(obj), referenceId: 1, subjectDescription: `STYLE ANCHOR — another set of this project (${String(other.name || "")}); match rendering style only`, referenceKind: "style" });
    return { refs, source: "other-set" };
  }
  const envAssets: any[] = Array.isArray(payload.environmentAssets) ? payload.environmentAssets : (Array.isArray(payload.knowledgeEnvironmentAssets) ? payload.knowledgeEnvironmentAssets : []);
  for (const ea of envAssets) {
    if (refs.length >= max) break;
    const url = String(ea?.imageDataUrl || ea?.imageUrl || ea?.refObjectName || ea?.objectName || "").trim();
    if (!url || /^(data:|blob:)/i.test(url)) continue;
    refs.push({ imageUrl: /^(gs:|https?:)/i.test(url) ? url : gsOf(url), referenceId: refs.length + 1, subjectDescription: `STYLE ANCHOR — brand hub environment asset "${String(ea?.name || ea?.label || "environment").slice(0, 60)}" (match rendering style, palette, materials and lighting only)`, referenceKind: "style" });
  }
  if (refs.length) return { refs, source: "hub-environment-assets" };
  const brandId = String(payload.brandId || payload.brandRef?.id || "").trim();
  if (brandId) {
    try {
      const got: any = await runBrandGetTool({ brandId }, ctx);
      const sheets = Array.isArray(got?.brand?.characterSheets) ? got.brand.characterSheets : [];
      for (const entry of sheets) {
        if (refs.length >= max) break;
        const items = Array.isArray(entry?.items) ? entry.items : [];
        const primary = items.find((it: any) => it?.isPrimary) || items[0];
        const url = String(primary?.imageDataUrl || "").trim();
        if (!url || /^(data:|blob:)/i.test(url)) continue;
        refs.push({ imageUrl: url, referenceId: refs.length + 1, subjectDescription: `STYLE ANCHOR — registered character sheet of ${String(entry?.displayName || entry?.token || "a character").replace(/^@+/, "")} (match the rendering style, palette and lighting ONLY; do NOT draw this character — the set is empty)`, referenceKind: "style" });
      }
      if (refs.length) return { refs, source: "brand-character-sheets" };
    } catch { /* 다음 후보 */ }
  }
  const stills: any[] = Array.isArray(cur?.scenes) ? cur.scenes : [];
  const still = stills.map((sc) => String(sc?.imagePath || sc?.imageDataUrl || "").trim()).find((v) => v && !/^(data:|blob:)/i.test(v));
  if (still && bucket) { refs.push({ imageUrl: /^(gs:|https?:)/i.test(still) ? still : gsOf(still), referenceId: 1, subjectDescription: "STYLE ANCHOR — an existing still of this project (match rendering style only)", referenceKind: "style" }); return { refs, source: "project-still" }; }
  return { refs, source: "" };
}

function findOrCreateLocation(locations: any[], name: string): number {
  const key = normLocationKey(name);
  let idx = locations.findIndex((l) => normLocationKey(l?.name) === key || normLocationKey(l?.id) === key);
  if (idx < 0) { locations.push({ id: key.replace(/[^0-9a-z가-힣]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 48) || "set", name, description: "", refObjectName: "", variants: [] }); idx = locations.length - 1; }
  return idx;
}

function setVariant(loc: any, id: string, objectName: string, label: string, extra: Record<string, any> = {}) {
  loc.variants = Array.isArray(loc.variants) ? loc.variants : [];
  const hit = loc.variants.find((v: any) => v && String(v.id || "") === id);
  if (hit) { hit.refObjectName = objectName; hit.label = label || hit.label; Object.assign(hit, extra); }
  else loc.variants.push({ id, label, description: "", refObjectName: objectName, ...extra });
}

/** 세트 마스터(부감) 플레이트: 배치의 단일 원천. 세트 전체를 위에서 내려다본 한 장(인물 없음), 평면도(layout)를 지킨다.
 *  variants 'angle-top' 에 저장, 앵커가 없으면 이 이미지가 프로젝트 스타일 앵커. 이후 set_angle 이 이 이미지를 편집해 다른 앵글을 만든다. */
async function runSetMasterTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!projectId) throw new Error("projectId is required");
  const name = String(input?.locationName || input?.name || input?.setName || "").trim();
  if (!name) throw new Error("locationName(세트 이름)이 필요해요");
  const cur = await runProjectGetTool({ projectId }, ctx);
  const payload: any = (cur.payload && typeof cur.payload === "object") ? cur.payload : {};
  const header = String(payload.header || cur.header || "");
  const aspect = String(input?.aspectRatio || payload.aspectRatio || "16:9");
  const resolution = String(input?.resolution || input?.imageSize || "1K").toUpperCase();
  const locations: any[] = Array.isArray(payload.episodeLocations) ? payload.episodeLocations.map((l: any) => ({ ...l })) : [];
  const idx = findOrCreateLocation(locations, name);
  const loc = locations[idx];
  const hub = buildHubContext(payload);
  const layout = (input?.layout && typeof input.layout === "object") ? input.layout : (loc.layout || null);
  const promptSetName = looksLikeSentenceLocation(String(loc.name || name)) ? (sanitizeSetName(String(loc.name || name)) || "the main set") : String(loc.name || name);
  const prompt = String(input?.prompt || "").trim() || buildSetMasterPrompt({ header, hub, set: { name: promptSetName, description: String(loc.description || ""), layout }, aspect });
  const bucket = studioBucket(ctx);
  const style = await collectStyleRefs(payload, locations, idx, cur, bucket, ctx, 2);
  const providerOpt = input?.provider ? { provider: String(input.provider) } : {};
  const img = await runImagenTool({ _imageStageKey: `set_master:${projectId}:${name}`, prompt, aspectRatio: aspect, projectId, referenceImages: style.refs, generationMode: "text-to-image", ...(["1K", "2K", "4K"].includes(resolution) ? { imageSize: resolution } : {}), ...providerOpt }, ctx);
  if (!img?.objectName) throw new Error("마스터 플레이트 결과에 저장 경로(objectName)가 없어요.");
  // ★새 마스터 = 새 진실. 옛 마스터(또는 옛 정면 플레이트)에서 파생·준비된 앵글 플레이트(dir-*, angle-*)와 정면 플레이트는 전부 무효.
  //   남겨 두면 scene_still 이 캐시된 옛 정면 플레이트를 "재사용"해 새 마스터가 무시된다(2026-09-14 재현). 세부 배경(v-*)은 유지.
  const staleIds = (Array.isArray(loc.variants) ? loc.variants : []).filter((v: any) => v && /^(dir-|angle-)/.test(String(v.id || ""))).map((v: any) => String(v.id));
  loc.variants = (Array.isArray(loc.variants) ? loc.variants : []).filter((v: any) => v && !/^(dir-|angle-)/.test(String(v.id || "")));
  const hadFrontPlate = !!String(loc.refObjectName || "").trim();
  loc.refObjectName = "";
  setVariant(loc, "angle-top", img.objectName, "부감(마스터)", { source: "master", createdAt: new Date().toISOString() });
  loc.masterAngle = "top";
  if (layout && !loc.layout) loc.layout = layout;
  loc.plateDiag = { provider: String(img.provider || ""), model: String(img.model || ""), geminiEndpoint: String(img.geminiEndpoint || ""), referenceCount: Number(img.referenceImageCount) || 0, styleSource: style.source, hubContextUsed: !!hub, promptHead: String(prompt).slice(0, 1200) };
  locations[idx] = loc;
  const nextPayload: any = { episodeLocations: locations };
  // 새 부감 마스터가 곧 프로젝트 스타일 기준이다. 사용자가 직접 고른 기준만 지킨다 — 옛 2×2 시트가 자동 기준으로 남으면 새 생성이 그 방을 베낀다.
  if (!(payload.styleAnchor && payload.styleAnchor.objectName && payload.styleAnchor.pickedBy === "user")) nextPayload.styleAnchor = { objectName: img.objectName, sheetId: "", setName: String(loc.name || name), createdAt: new Date().toISOString(), pickedBy: "auto-master" };
  await callInternalJson(ctx, "/api/project/save", { body: { projectId, payload: nextPayload } });
  return { kind: "set_master", projectId, locationName: String(loc.name || name), objectName: img.objectName, signedUrl: img.signedUrl || "", styleSource: style.source, hubContextUsed: !!hub, model: img.model || "", provider: img.provider || "", geminiEndpoint: img.geminiEndpoint || "", layoutUsed: !!layout, invalidatedPlates: staleIds, clearedFrontPlate: hadFrontPlate, saved: true, promptEcho: prompt, summary: `부감 마스터 플레이트 생성: ${String(loc.name || name)}${layout ? " (평면도 적용)" : " (평면도 없음 — 세트 계획을 다시 하면 생겨요)"}${staleIds.length || hadFrontPlate ? ` · 옛 앵글 플레이트 ${staleIds.length + (hadFrontPlate ? 1 : 0)}장 무효화(다음 컷 생성 때 새 마스터에서 다시 파생)` : ""}` };
}

/** 세트 앵글 플레이트 파생: 마스터(부감) 이미지를 소스로 같은 세트를 다른 앵글로 다시 그린다(카메라 재구성, 편집 모드).
 *  angle: front|back|left|right|high|low. front → refObjectName(정면 마스터, 기존 파이프라인 호환), back/left/right → dir-*, high/low → angle-*. */
async function runSetAngleTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!projectId) throw new Error("projectId is required");
  const name = String(input?.locationName || input?.name || input?.setName || "").trim();
  if (!name) throw new Error("locationName(세트 이름)이 필요해요");
  // 플레이트 키 = 방위 × 높이. 옛 angle(front|back|left|right|high|low) 도 받아 같은 키로 접는다.
  const angleRaw = String(input?.angle || "").trim().toLowerCase();
  let direction = normalizeCameraDirection(input?.direction) || "";
  let elevation = normalizeCameraElevation(input?.elevation) || "";
  if (!direction && angleRaw) direction = normalizeCameraDirection(angleRaw) || "front";
  if (!elevation && angleRaw) elevation = (angleRaw === "high" || angleRaw === "low") ? angleRaw : "eye";
  if (!direction) direction = "front";
  if (!elevation) elevation = "eye";
  if (plateElevation(elevation) === "top") throw new Error("부감(top)은 파생하지 않아요 — set_master 가 그 자체예요.");
  const angle = direction; // 호환용(응답 필드)
  const variantId = plateVariantId(direction, elevation);
  const cur = await runProjectGetTool({ projectId }, ctx);
  const payload: any = (cur.payload && typeof cur.payload === "object") ? cur.payload : {};
  const header = String(payload.header || cur.header || "");
  const aspect = String(input?.aspectRatio || payload.aspectRatio || "16:9");
  const locations: any[] = Array.isArray(payload.episodeLocations) ? payload.episodeLocations.map((l: any) => ({ ...l })) : [];
  const idx = findOrCreateLocation(locations, name);
  const loc = locations[idx];
  const bucket = studioBucket(ctx);
  const gsOf = (obj: any) => `gs://${bucket}/${String(obj || "").replace(/^gs:\/\/[^/]+\//, "")}`;
  const master = masterOf(loc) || loc.refObjectName || "";
  if (!master || !bucket) throw new Error("마스터 플레이트(부감)가 없어요. 먼저 set_master 로 만드세요.");
  const hub = buildHubContext(payload);
  const promptSetName = looksLikeSentenceLocation(String(loc.name || name)) ? (sanitizeSetName(String(loc.name || name)) || "the main set") : String(loc.name || name);
  const prompt = String(input?.prompt || "").trim() || buildAnglePlateEditPrompt({ set: { name: promptSetName, description: String(loc.description || ""), layout: loc.layout || null }, angle, direction, elevation, header, hub, fromMaster: true });
  const providerOpt = input?.provider ? { provider: String(input.provider) } : {};
  const img = await runImagenTool({
    prompt, aspectRatio: aspect, projectId, generationMode: "image-to-image", cameraTargetMode: "scene",
    _imageStageKey: `set_angle:${projectId}:${name}:${variantId}`,
    referenceImages: [{ imageUrl: gsOf(master), referenceId: 1, subjectDescription: `${promptSetName} — top-down master plate (source)`, referenceKind: "environment" }],
    ...providerOpt,
  }, ctx);
  if (!img?.objectName) throw new Error("앵글 플레이트 결과에 저장 경로(objectName)가 없어요.");
  const labelKo = plateLabel(direction, elevation, "ko");
  // 정면·아이레벨은 기존 파이프라인의 정면 플레이트(refObjectName)와 같은 뜻이라 둘 다 채운다.
  if (variantId === "dir-front") loc.refObjectName = img.objectName;
  setVariant(loc, variantId, img.objectName, labelKo, { source: "derived", direction, elevation: plateElevation(elevation), createdAt: new Date().toISOString() });
  locations[idx] = loc;
  await callInternalJson(ctx, "/api/project/save", { body: { projectId, payload: { episodeLocations: locations } } });
  return { kind: "set_angle", projectId, locationName: String(loc.name || name), angle, direction, elevation, variantId, objectName: img.objectName, signedUrl: img.signedUrl || "", model: img.model || "", provider: img.provider || "", geminiEndpoint: img.geminiEndpoint || "", saved: true, promptEcho: prompt, summary: `${labelKo} 플레이트를 마스터에서 파생했어요: ${String(loc.name || name)}` };
}

/** 스타일 앵커 지정: 프로젝트의 그림체 기준 이미지를 창작자가 고른다(기존 스틸·플레이트·시트 어느 것이든).
 *  이후 세트 시트·콘티·스틸컷이 이 이미지를 style 참조로 받는다. 쓰기 → 게이트(캔버스는 자동 승인). */
async function runStyleAnchorSetTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!projectId) throw new Error("projectId is required");
  // clear: 기준 해제. 다음 부감 마스터가 새 기준이 된다(결이 다른 옛 시트가 기준으로 잡혀 있을 때 쓴다).
  if (input?.clear === true) {
    await callInternalJson(ctx, "/api/project/save", { body: { projectId, payload: { styleAnchor: null } } });
    return { kind: "style_anchor_set", projectId, styleAnchor: null, saved: true, summary: "스타일 기준 이미지를 해제했어요. 다음에 만드는 부감 마스터가 새 기준이 돼요." };
  }
  const objectName = String(input?.objectName || "").replace(/^gs:\/\/[^/]+\//, "").trim();
  if (!objectName || /^(data:|blob:|https?:)/i.test(objectName)) throw new Error("objectName(저장소 경로)이 필요해요");
  const anchor = { objectName, sheetId: String(input?.sheetId || ""), setName: String(input?.setName || input?.label || ""), createdAt: new Date().toISOString(), pickedBy: "user" };
  await callInternalJson(ctx, "/api/project/save", { body: { projectId, payload: { styleAnchor: anchor } } });
  return { kind: "style_anchor_set", projectId, styleAnchor: anchor, saved: true, summary: `스타일 기준 이미지를 바꿨어요${anchor.setName ? ` (${anchor.setName})` : ""}` };
}

/** 씬 나누기/합치기: 컷의 sceneBreak(이 컷부터 새 씬)를 켜거나 끈다. 같은 세트 안에서 씬을 둘로 나누는 유일한 방법.
 *  캔버스(컷을 아래로 떼어냄 · 씬 바 ＋ · 이전 씬과 합치기)와 채팅("컷 5부터 새 씬")이 쓴다. 컷 순서·장소는 바꾸지 않는다. 쓰기 → 게이트. */
async function runSceneSplitTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || input?.id || "").trim();
  if (!projectId) throw new Error("projectId is required");
  const cur = await runProjectGetTool({ projectId }, ctx);
  const scenes: any[] = Array.isArray(cur.scenes) ? cur.scenes.slice() : [];
  const idx = findSceneIndex(scenes, input?.sceneId ?? input?.scene?.id ?? input?.sceneIndex);
  if (idx < 0) throw new Error(`씬을 찾지 못했어요(sceneId=${input?.sceneId ?? "?"}).`);
  const split = input?.split !== false && input?.merge !== true;
  if (split && idx === 0) throw new Error("첫 컷은 이미 첫 씬의 시작이에요.");
  const before = !!scenes[idx]?.sceneBreak;
  scenes[idx] = { ...scenes[idx], sceneBreak: split };
  if (before === split) {
    return { kind: "scene_split", projectId, sceneId: scenes[idx].id, split, changed: false, saved: false, summary: split ? "이미 새 씬의 시작이에요" : "이미 같은 씬이에요" };
  }
  const saved = await callInternalJson(ctx, "/api/project/save", { body: { projectId, scenes } });
  return { kind: "scene_split", projectId, sceneId: scenes[idx].id, split, changed: true, saved: true, objectName: saved?.objectName || "", summary: split ? `컷 ${scenes[idx].id}부터 새 씬으로 나눴어요` : `컷 ${scenes[idx].id}을(를) 앞 씬에 합쳤어요` };
}

