/**
 * 회사 지식 감사(정리 근거 수집): 축적된 회사 지식 전체 + '현재 능력 카탈로그'(도구·담당·쓰기여부)를
 * 함께 돌려줘, 코어가 "기능이 생겨/바뀌어 낡은 지식"·중복·모순을 스스로 찾아내게 한다.
 * 능력 카탈로그가 핵심 — 이게 없으면 "싱크는 드라이브 권한 없음" 같은 '기능 추가로 거짓이 된' 지식을 못 잡는다.
 * read+synthesize. 실제 삭제·수정은 코어가 보고→사람 승인 후 KNOW del/edit 마커로 반영.
 */
async function runKnowledgeAuditTool(input: any, ctx: ToolContext): Promise<any> {
  const sql = getSql(ctx.env);
  // 한 번에 전부 돌려주면 모델에 넘기는 결과가 잘려 뒤 항목이 사라진다 → 페이지 단위로 돌려준다.
  const offset = Math.max(0, Math.floor(Number(input?.offset) || 0));
  const limit = Math.min(50, Math.max(1, Math.floor(Number(input?.limit) || 20)));
  let items: { n: number; id: string; type: string; source: string; date: string; text: string }[] = [];
  let counts = { total: 0, knowledgeOnly: 0, breakdown: { rules: 0, facts: 0, decisions: 0, skills: 0 } };
  let exactDuplicates: { text: string; count: number }[] = [];
  if (sql) {
    try {
      counts = await companyKnowledgeCounts(sql, ctx.userId);
      const rows = await sql(
        "SELECT id, text, type, source, created_at FROM company_knowledge WHERE user_id = $1 ORDER BY created_at ASC, id ASC LIMIT $2 OFFSET $3",
        [ctx.userId, limit, offset]
      ) as any[];
      items = rows.map((r, i) => ({
        n: offset + i + 1,
        // KNOW del/edit 대상 지정용 짧은 id — 번호(n)는 삭제 뒤 밀리므로 대상 지정에 쓰지 않는다.
        id: `id:${String(r.id || "").replace(/-/g, "").slice(0, 8)}`,
        type: r.type || "사실",
        source: r.source || "",
        date: r.created_at ? String(r.created_at).slice(0, 10) : "",
        text: String(r.text || ""),
      }));
      if (offset === 0) {
        const dups = await sql(
          "SELECT text, count(*)::int AS count FROM company_knowledge WHERE user_id = $1 GROUP BY text HAVING count(*) > 1 ORDER BY count(*) DESC LIMIT 50",
          [ctx.userId]
        ) as any[];
        exactDuplicates = dups.map((r) => ({ text: String(r.text || ""), count: Number(r.count || 0) }));
      }
    } catch (_) { items = []; }
  }
  const nextOffset = offset + items.length;
  // 페이지는 지식만 넘긴다(스킬은 항목에 없음) → 이어보기 판단도 knowledgeOnly 기준.
  const hasMore = items.length > 0 && nextOffset < counts.knowledgeOnly;
  // 현재 능력 카탈로그 — 도구명(담당 직원, 쓰기여부). 지식이 이 능력과 모순되면 낡은 것. 첫 페이지에만 싣는다.
  const capabilities = offset === 0
    ? Object.entries(AGENT_TOOLS).map(([tool, def]: [string, any]) => {
      const agents = [def.agentId, ...((def.agentIds as string[]) || [])].filter(Boolean);
      return `${tool} — 담당:${agents.join("/")}${def.gate ? " (쓰기·승인)" : ""}`;
    })
    : [];
  return {
    kind: "knowledge_audit",
    // total = 화면 '회사 지식 N'과 같은 기준(지식 + 활성 스킬). 지식 삭제 전후 비교는 knowledgeOnly 로 한다.
    total: counts.total,
    knowledgeOnly: counts.knowledgeOnly,
    breakdown: counts.breakdown,
    countBasis: "total=지식(원칙·사실·결정)+스킬 = 화면 '회사 지식 N' / knowledgeOnly=지식만(KNOW 마커 전후 비교 기준) / items는 지식만",
    offset,
    limit,
    items,
    hasMore,
    nextOffset,
    ...(offset === 0 ? { exactDuplicates, capabilityCount: capabilities.length, capabilities } : {}),
  };
}

/** 회사 지식 검색(색인): 프롬프트에 안 들어간 지식을 단어·의미로 찾아 근거로 쓴다. read+synthesize. */
async function runCompanyKnowledgeSearchTool(input: any, ctx: ToolContext): Promise<any> {
  const query = String(input?.query || input?.prompt || "").trim();
  if (!query) throw new Error("찾을 내용(query)이 필요해요.");
  const sql = getSql(ctx.env);
  if (!sql) throw new Error("DATABASE_URL 미설정");
  const types = (Array.isArray(input?.types) ? input.types : input?.type ? [input.type] : [])
    .map((value: any) => (/규칙|원칙/.test(String(value)) ? "원칙" : /결정/.test(String(value)) ? "결정" : /사실/.test(String(value)) ? "사실" : ""))
    .filter(Boolean);
  const limit = Math.min(30, Math.max(1, Number(input?.limit) || 10));
  const hits = await searchCompanyKnowledge(ctx.env, sql, ctx.userId, query, {
    projectId: String(input?.projectId || "").trim() || undefined, types, limit, embedTimeoutMs: 6000,
  });
  return {
    kind: "company_knowledge_search",
    query,
    count: hits.length,
    items: hits.map((hit) => ({ id: shortKnowledgeId(hit.id), type: hit.type, date: hit.createdAt.slice(0, 10), projectId: hit.projectId, text: hit.text, via: hit.via })),
  };
}

/** SNS 채널 연결 상태: /api/agent/integrations. read. (연결 개설/해제는 사람 직접) */
/**
 * SNS 채널 상태 = 브랜드 스튜디오 SNS 설정과 같은 눈높이(자동 발행 채널 6 + 직접 올리기 채널 4).
 * 전엔 직원 연동 목록(/api/agent/integrations: Gmail·캘린더 …)을 읽어 이름 없는 "채널" 12줄만 찍고 끝났다(2026-09-24).
 */
async function runSnsChannelsStatusTool(_input: any, ctx: ToolContext): Promise<any> {
  const auto = await listConnectedPublishChannels(ctx);
  const LABEL: Record<string, string> = { instagram: "Instagram", "youtube-shorts": "YouTube(쇼츠)", tiktok: "TikTok", threads: "Threads", x: "X", facebook: "Facebook" };
  const channels = auto.map((c) => ({
    platform: c.platform, name: LABEL[c.platform] || c.platform, account: c.account, mode: "auto",
    connected: c.connected, enabled: c.enabled, needsReconnect: c.needsReconnect,
    publishable: c.connected && c.enabled && !c.needsReconnect,
    status: !c.connected ? "미연결" : c.needsReconnect ? "재연결 필요(SNS 설정)" : !c.enabled ? "사용 중지" : "발행 가능",
  }));
  const manual = ["네이버 블로그", "카카오", "네이버 포스트", "BAND"].map((name) => ({ platform: name, name, account: "", mode: "manual", connected: false, enabled: true, needsReconnect: false, publishable: false, status: "직접 올리기(자동 발행 없음)" }));
  return {
    kind: "sns_channels_status", count: channels.length + manual.length, channels: [...channels, ...manual],
    publishable: channels.filter((c) => c.publishable).map((c) => c.platform),
    note: "publish 도구는 platforms:[\"all\"] 이면 발행 가능한 채널을 스스로 고르므로, 발행 전에 이 조회를 따로 할 필요는 없다.",
  };
}

/** 미디어 라이브러리 통합 조회: image_library + video_library 합산. read+synthesize. */
async function runMediaLibraryTool(input: any, ctx: ToolContext): Promise<any> {
  const projectId = String(input?.projectId || "ai-company").trim() || "ai-company";
  const [img, vid] = await Promise.all([
    runImageLibraryTool({ projectId }, ctx).catch(() => ({ items: [] as any[] })),
    runVideoLibraryTool({ projectId }, ctx).catch(() => ({ items: [] as any[] })),
  ]);
  const images = Array.isArray(img.items) ? img.items : [];
  const videos = Array.isArray(vid.items) ? vid.items : [];
  return { kind: "media_library", projectId, imageCount: images.length, videoCount: videos.length, images: images.slice(0, 30), videos: videos.slice(0, 30) };
}

