/** 키 순서와 무관하게 같은 값이면 같은 문자열이 나오도록 직렬화한다. */
function stableStringify(value: any): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value ?? null) ?? "null";
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(",")}]`;
  const keys = Object.keys(value).sort();
  return `{${keys.map((k) => `${JSON.stringify(k)}:${stableStringify(value[k])}`).join(",")}}`;
}

/**
 * 승인 요청의 정체성. 같은 값이면 '같은 일감'이라 카드를 하나로 합친다.
 * 도구가 approvalKey 를 주면 그것을, 아니면 입력 전체를 정규화해서 쓴다.
 */
export function approvalIdentity(type: string, input: any): string {
  const tool = AGENT_TOOLS[type];
  if (tool?.approvalKey) {
    try { return `${type}:${tool.approvalKey(input ?? {})}`; } catch { /* 아래 기본값으로 */ }
  }
  return `${type}:${stableStringify(input ?? {})}`;
}

/**
 * 같은 일감으로 이미 대기 중인 승인을 취소한다(마지막 요청이 이긴다).
 *
 * 먼저 온 것을 남기면 모델이 다듬어 보낸 최신 내용이 버려진다. 사용자가 보는 건
 * 늘 '가장 최근에 요청한 그 내용' 한 장이어야 한다. 취소한 개수를 돌려준다.
 */
export async function supersedePendingApprovals(
  sql: SqlFn, userId: string, type: string, input: any, keepJobId: string
): Promise<number> {
  const identity = approvalIdentity(type, input);
  const rows = await sql(
    "SELECT id, input FROM agent_jobs WHERE user_id = $1 AND type = $2 AND status = 'review_pending' AND id <> $3",
    [userId, type, keepJobId]
  ).catch(() => [] as any[]);
  const stale = (rows as any[]).filter((r) => {
    const raw = typeof r.input === "string" ? (() => { try { return JSON.parse(r.input); } catch { return {}; } })() : r.input;
    return approvalIdentity(type, raw) === identity;
  });
  for (const r of stale) {
    await sql(
      "UPDATE agent_jobs SET status = 'cancelled', updated_at = now() WHERE id = $1 AND user_id = $2 AND status = 'review_pending'",
      [r.id, userId]
    ).catch(() => {});
  }
  return stale.length;
}

/** 도구 실행 파이프라인: working → tool.run → review_pending | error. (job.ts·오케스트레이터 공용) */
export async function processJob(
  ctx: ToolContext,
  sql: SqlFn,
  jobId: string,
  type: string,
  input: any
): Promise<{ ok: boolean; error?: string; gated?: boolean; pending?: boolean; output?: any; superseded?: number; input?: any }> {
  try {
    const tool = AGENT_TOOLS[type];
    if (!tool) throw new Error(`unknown tool: ${type}`);
    // 승인 게이트 도구: 승인 전에는 실행하지 않는다. 승인 대기로만 두고, 승인 시 review.ts에서 run 실행.
    if (tool.gate && !ctx.runApproved) {
      if (tool.prepare) {
        const prepared = await tool.prepare(input, { ...ctx, jobId });
        if (prepared && typeof prepared === "object") {
          input = prepared;
          await sql("UPDATE agent_jobs SET input = $1::jsonb, updated_at = now() WHERE id = $2 AND user_id = $3", [JSON.stringify(prepared), jobId, ctx.userId]);
        }
      }
      input = { ...input, _conversationId: ctx.conversationId || input?._conversationId || 'main' };
      await sql('UPDATE agent_jobs SET input = $1::jsonb, updated_at = now() WHERE id = $2 AND user_id = $3', [JSON.stringify(input), jobId, ctx.userId]);
      await setJobStatus(sql, jobId, ctx.userId, { status: "review_pending", reviewStatus: "pending" });
      // 같은 일감이 이미 대기 중이면 그 카드를 걷어낸다 — 패널엔 최신 요청 한 장만 남는다.
      const superseded = await supersedePendingApprovals(sql, ctx.userId, type, input, jobId).catch(() => 0);
      return { ok: true, gated: true, superseded, input };
    }
    await setJobStatus(sql, jobId, ctx.userId, { status: "working" });
    const output = await tool.run(input, { ...ctx, jobId });
    await setJobStatus(sql, jobId, ctx.userId, { status: ctx.runApproved ? 'approved' : 'review_pending', output,
      reviewStatus: ctx.runApproved ? 'approved' : 'pending' });
    return { ok: true, output };
  } catch (e: any) {
    if (e.imageJobId) {
      const output = await persistPendingImage(ctx, sql, jobId, e);
      return { ok: true, pending: true, output };
    }
    if (e.videoJobId) {
      const output = await persistPendingVideo(ctx, sql, jobId, e);
      return { ok: true, pending: true, output };
    }
    const error = String(e?.message || e || "tool_failed");
    await setJobStatus(sql, jobId, ctx.userId, { status: "error", error });
    return { ok: false, error };
  }
}

export async function persistPendingImage(ctx: ToolContext, sql: SqlFn, jobId: string, error: any) {
  const output = { subscriptionPending: true, imageJobId: error.imageJobId, imageRequestKey: error.imageRequestKey,
    imageResults: error.imageResults, conversationId: ctx.conversationId || 'main', runApproved: ctx.runApproved === true };
  await setJobStatus(sql, jobId, ctx.userId, { status: 'working', output,
    ...(ctx.runApproved ? { reviewStatus: 'approved' as const } : {}) });
  return output;
}

/** 영상 제출 신호를 잡에 남긴다: status=working, output.videoPending=true. 완료는 reconcileVideoJobs 가 닫는다. */
export async function persistPendingVideo(ctx: ToolContext, sql: SqlFn, jobId: string, signal: any) {
  const output = {
    videoPending: true,
    videoJobId: String(signal.videoJobId || ""),
    videoModel: String(signal.videoModel || ""),
    durationSeconds: Number(signal.durationSeconds) || 0,
    promptEcho: String(signal.promptEcho || ""),
    ...(signal.attach ? { attach: signal.attach } : {}),
    conversationId: ctx.conversationId || 'main',
    runApproved: ctx.runApproved === true,
    submittedAt: new Date().toISOString(),
  };
  await setJobStatus(sql, jobId, ctx.userId, { status: 'working', output,
    ...(ctx.runApproved ? { reviewStatus: 'approved' as const } : {}) });
  return output;
}

/** 외부 영상 모델이 이보다 오래 걸리면 실패로 닫는다(무한 '진행 중' 방지). */
export const VIDEO_PENDING_MAX_MS = 30 * 60 * 1000;
// 패널이 4초마다 폴링하므로 공급자 상태 조회는 이 간격으로만 한다(서브요청·Neon 전송량 절약).
const VIDEO_CHECK_INTERVAL_SQL = "8 seconds";

/**
 * 제출해 둔 영상 잡의 완료를 확인해 마무리한다(짧은 인증 폴링 요청마다 호출: jobs·job·messages).
 *  - 완료: 결과 URL 을 output 에 넣고, scene_video 면 컷에 부착·저장. 승인 후 실행이었으면 approved+업무 등록, 아니면 검수 대기.
 *  - 실패·시간 초과: error 로 닫고 이유를 채팅에 남긴다.
 *  - 진행 중: 아무것도 하지 않는다(리스만 갱신).
 */
export async function reconcileVideoJobs(ctx: ToolContext, sql: SqlFn) {
  const pending = await sql(`SELECT id FROM agent_jobs WHERE user_id=$1 AND status='working'
    AND output->>'videoPending'='true' ORDER BY created_at LIMIT 10`, [ctx.userId]);
  if (!pending.length) return;
  for (const row of pending) {
    const [job] = await sql(`UPDATE agent_jobs SET output=jsonb_set(output,'{checkedAt}',to_jsonb(now()::text)),updated_at=now()
      WHERE user_id=$1 AND id=$2 AND status='working' AND output->>'videoPending'='true'
      AND (output->>'checkedAt' IS NULL OR (output->>'checkedAt')::timestamptz < now()-interval '${VIDEO_CHECK_INTERVAL_SQL}') RETURNING *`,
      [ctx.userId, row.id]);
    if (!job) continue;
    const out: any = job.output && typeof job.output === "object" ? job.output : {};
    const conversationId = out.conversationId || 'main';
    const runApproved = out.runApproved === true;
    const meta = AGENT_META[job.agent_id] || { name: job.agent_id, role: "" };
    const label = `${out.videoModel || "video"} · ${out.durationSeconds || "?"}초`;
    const say = (text: string, files: MessageFileReference[] = []) => addMessage(sql, {
      userId: ctx.userId, conversationId, role: 'agent', agentId: job.agent_id, backgroundJobId: job.id,
      name: meta.name, text, files,
    });
    let check: { state: "processing" | "done" | "error"; videoUrl: string; error: string };
    try { check = await checkVideoJob(ctx, out.videoJobId); }
    catch { continue; } // 상태 서버 일시 오류 — 다음 폴링에 다시 본다.
    if (check.state === "processing") {
      const started = Date.parse(String(out.submittedAt || job.created_at || ""));
      if (Number.isFinite(started) && Date.now() - started > VIDEO_PENDING_MAX_MS) {
        const error = `영상 생성이 ${Math.round(VIDEO_PENDING_MAX_MS / 60000)}분 넘게 끝나지 않아 종료했어요(${label}, videoJobId=${out.videoJobId}).`;
        await setJobStatus(sql, job.id, ctx.userId, { status: 'error', error });
        await say(`❌ ${error}`);
      }
      continue;
    }
    if (check.state === "error") {
      const error = `영상 생성 실패(${label}): ${check.error}`;
      await setJobStatus(sql, job.id, ctx.userId, { status: 'error', error });
      await say(`❌ ${error}`);
      continue;
    }
    let output: any;
    try {
      output = out.attach
        ? await attachSceneVideo(ctx, out.attach, check.videoUrl)
        : { kind: "video", videoUrl: check.videoUrl, promptEcho: out.promptEcho };
    } catch (e: any) {
      const error = `영상은 완성됐지만 컷에 붙이지 못했어요: ${String(e?.message || e)} (videoUrl=${check.videoUrl})`;
      await setJobStatus(sql, job.id, ctx.userId, { status: 'error', error });
      await say(`❌ ${error}`);
      continue;
    }
    const objectName = String(output.objectName || "").trim() || mediaObjectNameFromUrl(check.videoUrl);
    output = { ...output, model: out.videoModel || output.model || "", durationSeconds: out.durationSeconds || 0, videoJobId: out.videoJobId,
      ...(objectName ? { objectName } : {}) };
    await setJobStatus(sql, job.id, ctx.userId, {
      status: runApproved ? 'approved' : 'review_pending', output,
      reviewStatus: runApproved ? 'approved' : 'pending',
    });
    if (runApproved && hasDeliverableOutput(output)) {
      const filed = await fileJobAsWorkItem(sql, ctx.userId, job, output).catch(() => null);
      if (filed) await setJobStatus(sql, job.id, ctx.userId, { output: { ...output, workItemId: filed.workId, workDateKey: filed.dateKey } });
    }
    const where = out.attach ? ` 컷 ${out.attach.sceneId} 에 붙여 저장했어요.` : " 검수 패널에서 확인하세요.";
    await say(`🎬 영상 생성 완료 (${label}).${where}`, messageFilesFromToolOutput(job.type, output, job.id));
  }
}

/**
 * 폴링마다 도는 정비 작업(만료·완료 확인·경로 복원)을 한 곳에서, 사용자별 20초에 한 번만 돈다.
 * 오늘(2026-09-24) 영상·틱톡 추적, 경로 복원, working 만료를 하나씩 붙이면서 4초 폴링 한 번에 Neon 쿼리가 2회 → 6~8회로 늘었다.
 * Neon 은 전송량·컴퓨트 한도가 있어(9/16 5GB 초과 사고) 이런 상시 쿼리가 곧 "Neon SQL 오류 520/500" 으로 돌아온다.
 * 결과 반영 지연은 최대 20초 — 사람이 체감할 수준이 아니다. 이 함수 밖에서 정비 작업을 따로 부르지 말 것.
 */
const MAINTENANCE_INTERVAL_MS = 20_000;
const maintenanceLastRun = new Map<string, number>();
export async function runJobMaintenance(ctx: ToolContext, sql: SqlFn, opts: { items?: any[]; force?: boolean } = {}): Promise<boolean> {
  const last = maintenanceLastRun.get(ctx.userId) || 0;
  if (!opts.force && Date.now() - last < MAINTENANCE_INTERVAL_MS) return false;
  maintenanceLastRun.set(ctx.userId, Date.now());
  if (maintenanceLastRun.size > 500) maintenanceLastRun.clear();
  await expireStaleQueuedAgentJobs(sql, ctx.userId).catch(() => 0);
  await expireStaleWorkingAgentJobs(sql, ctx.userId).catch(() => 0);
  await reconcileSubscriptionJobs(ctx, sql).catch(() => {});
  await reconcileVideoJobs(ctx, sql).catch(() => {});
  await reconcileTikTokJobs(ctx, sql).catch(() => {});
  if (opts.items?.length) await healMediaObjectNames(sql, ctx.userId, opts.items).catch(() => 0);
  return true;
}

/** TikTok 초안함 전송이 이보다 오래 "processing" 이면 추적을 멈추고 앱에서 직접 확인하라고 알린다. */
export const TIKTOK_PENDING_MAX_MS = 30 * 60 * 1000;

/**
 * 승인 실행된 TikTok 초안함 전송(publish 잡 output.tiktok.status === "processing")의 뒤를 잇는다.
 * 서버는 제출 뒤 6초만 기다리고 "처리 중" 으로 돌려주는데, 그 뒤를 아무도 보지 않아 사용자가 앱을 열어도
 * 영상이 없을 때 원인을 알 수 없었다(2026-09-24). 폴링 요청마다 publish-status 를 물어 완료·실패·시간 초과를 채팅에 알린다.
 */
export async function reconcileTikTokJobs(ctx: ToolContext, sql: SqlFn) {
  const rows = await sql(`SELECT id FROM agent_jobs WHERE user_id=$1 AND type='publish'
    AND output->'tiktok'->>'status'='processing' AND created_at > now() - interval '2 days' ORDER BY created_at DESC LIMIT 5`, [ctx.userId])
    .catch(() => [] as any[]);
  if (!(rows as any[]).length) return;
  for (const row of rows as any[]) {
    const [job] = await sql(`UPDATE agent_jobs SET output=jsonb_set(output,'{tiktok,checkedAt}',to_jsonb(now()::text)),updated_at=now()
      WHERE user_id=$1 AND id=$2 AND output->'tiktok'->>'status'='processing'
      AND (output->'tiktok'->>'checkedAt' IS NULL OR (output->'tiktok'->>'checkedAt')::timestamptz < now()-interval '${VIDEO_CHECK_INTERVAL_SQL}') RETURNING *`,
      [ctx.userId, row.id]).catch(() => [] as any[]);
    if (!job) continue;
    const out: any = job.output && typeof job.output === "object" ? job.output : {};
    const tk: any = out.tiktok || {};
    const conversationId = String((typeof job.input === "object" && job.input?._conversationId) || out.conversationId || "main");
    const meta = AGENT_META[job.agent_id] || { name: job.agent_id, role: "" };
    const say = (text: string) => addMessage(sql, { userId: ctx.userId, conversationId, role: 'agent', agentId: job.agent_id, backgroundJobId: job.id, name: meta.name, text });
    const finish = async (status: string, extra: Record<string, any> = {}) => {
      await setJobStatus(sql, job.id, ctx.userId, { output: { ...out, tiktok: { ...tk, ...extra, status, checkedAt: new Date().toISOString() } } });
    };
    let data: any = null;
    try {
      const res = await fetch(internalUrl(ctx.request, `/api/sns/tiktok/publish-status?publishId=${encodeURIComponent(String(tk.publishId || ""))}`), { headers: { Authorization: ctx.authHeader } });
      data = await res.json().catch(() => null);
      if (!res.ok || !data?.ok) {
        if (res.status === 412 || data?.error === "tiktok_reconnect_required") {
          await finish("reconnect_required", { failReason: "tiktok_reconnect_required" });
          await say("❌ TikTok 초안함 전송 상태를 확인하려다 연결이 끊긴 걸 발견했어요. 브랜드 스튜디오에서 TikTok 을 다시 연결한 뒤 다시 보내주세요.");
        }
        continue; // 일시 오류는 다음 폴링에
      }
    } catch { continue; }
    const status = String(data.status || "processing");
    if (status === "complete") {
      await finish("sent_to_inbox", { postId: data.postId || "", completedAt: new Date().toISOString() });
      await say("✅ TikTok 초안함에 영상이 도착했어요. " + "틱톡 앱 아래 '받은 알림함(Inbox)' 탭에 '영상이 준비됐어요' 알림으로 와요 — 그 알림을 누르면 편집 화면이 열리고, 공개 범위를 고른 뒤 '게시' 를 눌러야 올라가요(프로필의 자물쇠 탭은 비공개 영상, 초안 카드는 앱에서 직접 저장한 초안이라 거기엔 없어요).");
      continue;
    }
    if (status === "failed") {
      await finish("status_reported_failed", { failReason: String(data.failReason || "") });
      await say(`⚠️ TikTok 이 초안함 전송을 실패로 보고했어요${data.failReason ? ` (${data.failReason})` : ""}. 다만 실패로 보고돼도 실제로는 들어가 있는 경우가 있어 앱 초안함을 한 번 확인해 주시고, 없으면 다시 보내 달라고 해 주세요.`);
      continue;
    }
    const started = Date.parse(String(tk.sentAt || job.created_at || ""));
    if (Number.isFinite(started) && Date.now() - started > TIKTOK_PENDING_MAX_MS) {
      await finish("timeout");
      await say(`⏱️ TikTok 초안함 전송이 ${Math.round(TIKTOK_PENDING_MAX_MS / 60000)}분째 "처리 중" 으로만 나와요(publishId ${tk.publishId}). 틱톡 앱 초안함에 없으면 영상 형식·길이 문제일 수 있으니 다시 보내 달라고 해 주세요.`);
    }
  }
}

// Resume from a persisted queue result on short authenticated polling requests.
// No long waitUntil, no second generation, and no success card for an empty URL.
export async function reconcileSubscriptionJobs(ctx: ToolContext, sql: SqlFn) {
  const pending = await sql(`SELECT * FROM agent_jobs WHERE user_id=$1 AND status='working'
    AND output->>'subscriptionPending'='true' ORDER BY created_at LIMIT 10`, [ctx.userId]);
  if (!pending.length) return;
  await connectorSql(ctx.env);
  await expireImageJobs(sql, ctx.userId);
  for (const job of pending) {
    const [image] = await sql('SELECT id,status,result,error FROM nk_subscription_image_jobs WHERE user_id=$1 AND id=$2',
      [ctx.userId, job.output.imageJobId]);
    if (image && !['done', 'error', 'cancelled'].includes(image.status)) continue;
    const [claimed] = await sql(`UPDATE agent_jobs SET output=jsonb_set(output,'{resuming}','true'),updated_at=now()
      WHERE user_id=$1 AND id=$2 AND status='working' AND output->>'imageJobId'=$3
      AND (COALESCE(output->>'resuming','false')='false' OR updated_at<now()-interval '1 minute') RETURNING *`,
      [ctx.userId, job.id, job.output.imageJobId]);
    if (!claimed) continue;
    const conversationId = job.output.conversationId || 'main';
    let result: any;
    if (!image || image.status !== 'done') {
      const error = image?.error || 'subscription_image_result_missing';
      await setJobStatus(sql, job.id, ctx.userId, { status: 'error', error });
      result = { ok: false, error };
    } else {
      result = await processJob({ ...ctx, conversationId, runApproved: job.output.runApproved === true, imageResults: {
        ...job.output.imageResults, [job.output.imageRequestKey]: image.result } }, sql, job.id, job.type, job.input);
    }
    if (result.pending) continue;
    const output = result.output;
    if (result.ok && job.output.runApproved) {
      const filed = await fileJobAsWorkItem(sql, ctx.userId, job, output);
      if (filed) await setJobStatus(sql, job.id, ctx.userId, { output: { ...output, workItemId: filed.workId, workDateKey: filed.dateKey } });
    }
    await addMessage(sql, { userId: ctx.userId, conversationId, role: 'agent', agentId: job.agent_id, backgroundJobId: job.id,
      name: AGENT_META[job.agent_id]?.name || job.agent_id,
      text: result.ok ? `✅ ${job.type} 작업 완료. 본인 ChatGPT 구독으로 생성·저장했습니다. 검수 패널에서 확인하세요.`
        : `❌ ${job.type} 실패: ${result.error}. 마스터 인증으로 전환하지 않았습니다.`,
      files: result.ok && output?.signedUrl ? [{ source: 'generated', jobId: job.id,
        name: 'image.png', contentType: 'image/png', kind: 'image' }] : [] });
  }
}

